public._bank_cuenta_de_empresa(uuid)	20261029T0753_b01c_servicio_y_proveedor	CREATE OR REPLACE FUNCTION public._bank_cuenta_de_empresa(p_company uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v uuid;\nbegin\n  select account_id into v from public.company where id = p_company;\n  if v is null then raise exception 'La empresa no existe.' using errcode = 'P0002'; end if;\n  if not public.current_user_is_admin_or_manager_of(v) then\n    raise exception 'Solo un administrador o un encargado de la cuenta trabaja los bancos.' using errcode = '42501';\n  end if;\n  return v;\nend $function$\n	86f34d5afa7acfa379cca8fdcc077518	2026-10-29 09:22:37.75812+00
public._clock_entry_quien_y_hora()	20261027T1905_l1a_fichar_en_el_servidor	CREATE OR REPLACE FUNCTION public._clock_entry_quien_y_hora()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_cuenta uuid;\nbegin\n  -- El servidor (funciones con la clave de servicio, SQL) no pasa por aquí.\n  if auth.uid() is null then return new; end if;\n  v_cuenta := coalesce(new.account_id, (select e.account_id from public.employees e where e.id = new.employee_id));\n  -- El administrador y el encargado pueden poner una marca a otra persona\n  -- (kiosko, ficha, correcciones): deja rastro en la auditoría (abajo).\n  if public.current_user_is_admin_or_manager_of(v_cuenta) then return new; end if;\n  -- El trabajador, solo para sí mismo.\n  if not public.current_user_is_employee(new.employee_id, v_cuenta) then\n    raise exception 'NO_AUTORIZADO: solo puedes fichar por ti'\n      using hint = 'Solo puedes fichar por ti. Si hay que corregir el fichaje de otra persona, lo hace el encargado.', errcode = '42501';\n  end if;\n  if coalesce(new.source, '') = 'manual' then\n    raise exception 'NO_AUTORIZADO: una marca puesta a mano la pone el encargado'\n      using hint = 'Para corregir un fichaje, pide la corrección desde «Mis fichajes».', errcode = '42501';\n  end if;\n  -- La hora es la del servidor. La «efectiva» (redondeada al turno) se respeta\n  -- solo si cae a menos de 30 min de ahora; si no, también es la del servidor.\n  new.real_datetime := now();\n  if new.datetime is null or abs(extract(epoch from (new.datetime - now()))) > 1800 then\n    new.datetime := now();\n  end if;\n  return new;\nend $function$\n	c699b6abda3e1966630ee933dbf0e4d7	2026-10-28 05:46:23.932303+00
public._compras_camino_calcula(uuid)	20261029T1012_s01c_facturas_solas	CREATE OR REPLACE FUNCTION public._compras_camino_calcula(p_recepcion uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  g goods_receipt; s supplier; sp supplier; d record; v_doc jsonb; v_tipo text; v_nombre text; v_nif text;\n  v_unica uuid; v_es_factura boolean; v_path text; v_company uuid; v_sup uuid; v_how text;\n  v_q text; v_qd jsonb; v_reason text; v_modo text; v_sugerida text;\n  c_modo constant jsonb := '{"per_delivery": "con cada entrega", "delivery_note_then_invoice": "entrega con albarán y factura después", "monthly_settlement": "liquidación mensual"}';\nbegin\n  select * into g from goods_receipt where id = p_recepcion;\n  if g.id is null then raise exception 'Esa recepción no existe.' using errcode = 'P0002'; end if;\n  if g.status = 'anulado' then\n    return jsonb_build_object('path', 'anulada', 'supplier_id', g.supplier_id, 'reason', 'La recepción está anulada.');\n  end if;\n  select * into s from supplier where id = g.supplier_id;\n  v_modo := s.invoicing_mode;\n  v_unica := (select case when count(*) = 1 then min(c.id::text)::uuid end from company c where c.account_id = g.account_id and c.is_active);\n  select a.parsed_result->'document' into v_doc from goods_receipt_ai_session a where a.id = g.ai_session_id;\n  v_tipo := nullif(v_doc->>'doc_type', '');\n  v_nombre := nullif(btrim(v_doc->>'bill_to_name'), '');\n  v_nif := nullif(btrim(v_doc->>'bill_to_tax_id'), '');\n  v_sup := g.supplier_id;\n\n  if s.id is null then\n    v_path := 'sin_decidir'; v_how := 'ficha'; v_q := 'sin_papel';\n    v_reason := 'La recepción no tiene proveedor: no se sabe cómo factura.';\n  elsif v_tipo is null then\n    -- Sin papel leído: manda la ficha.\n    v_how := 'ficha'; v_company := v_unica;\n    if v_modo = 'monthly_settlement' then\n      v_path := 'liquidacion'; v_reason := format('No hay documento leído; %s liquida cada mes.', s.name);\n    elsif v_modo = 'delivery_note_then_invoice' then\n      v_path := 'pendiente_factura'; v_reason := format('No hay documento leído; %s manda la factura después.', s.name);\n    else\n      v_path := 'pendiente_factura'; v_q := 'sin_papel';\n      v_reason := case when v_modo = 'per_delivery'\n        then format('No hay documento leído y %s factura con cada entrega: sube su factura.', s.name)\n        else format('No hay documento leído y no se sabe cómo factura %s: queda pendiente de factura.', s.name) end;\n    end if;\n  else\n    v_es_factura := v_tipo in ('factura', 'albaran_factura');\n    select * into d from public._compras_destinatario(g.account_id, v_nombre, v_nif);\n    v_how := d.how;\n    if d.kind = 'empresa' then\n      v_company := d.company_id;\n      v_path := case when v_es_factura then 'factura' else 'pendiente_factura' end;\n      v_reason := case when v_es_factura then 'Es una factura a nombre de tu empresa.' else 'Es un albarán a nombre de tu empresa: queda pendiente de factura.' end;\n      v_sugerida := case when v_es_factura then 'per_delivery' else 'delivery_note_then_invoice' end;\n      if v_modo is null then\n        v_q := 'ficha_sin_forma';\n      elsif v_modo = 'per_delivery' and not v_es_factura then\n        v_q := 'papel_y_ficha';\n      elsif v_modo = 'delivery_note_then_invoice' and v_es_factura then\n        v_q := 'papel_y_ficha';\n      elsif v_modo = 'monthly_settlement' then\n        v_q := 'papel_y_ficha'; v_sugerida := null;\n        v_reason := v_reason || format(' La ficha dice que %s liquida cada mes.', s.name);\n      end if;\n      if v_q is not null then\n        v_qd := jsonb_build_object('ficha', v_modo, 'ficha_dice', c_modo->>v_modo, 'papel', v_tipo, 'sugerida', v_sugerida, 'sugerida_dice', c_modo->>v_sugerida);\n      end if;\n    elsif d.kind = 'proveedor' then\n      select * into sp from supplier where id = d.supplier_id;\n      if sp.invoicing_mode = 'monthly_settlement' then\n        v_path := 'liquidacion'; v_sup := sp.id; v_company := v_unica;\n        v_reason := case when sp.id = s.id then format('Va a nombre de %s, que liquida cada mes: entra en su liquidación.', sp.name)\n                         else format('Lo trae %s a nombre de %s, que liquida cada mes: entra en su liquidación.', s.name, sp.name) end;\n      elsif sp.invoicing_mode is null then\n        v_path := 'sin_decidir'; v_q := 'a_nombre_de';\n        v_reason := format('Va a nombre de %s, y su ficha no dice si liquida cada mes.', sp.name);\n        v_qd := jsonb_build_object('nombre', v_nombre, 'nombre_norm', public.compras_nombre_norm(v_nombre), 'proveedor', sp.id, 'proveedor_nombre', sp.name);\n      else\n        v_path := 'a_nombre_de_otro'; v_q := 'a_nombre_de_otro'; v_sup := g.supplier_id;\n        v_reason := format('Va a nombre de %s, no de tu empresa: así no se puede deducir el IVA.', sp.name);\n      end if;\n    elsif d.kind = 'otro' then\n      v_path := 'a_nombre_de_otro'; v_q := 'a_nombre_de_otro';\n      v_reason := format('Va a nombre de «%s», no de tu empresa: así no se puede deducir el IVA.', v_nombre);\n    else\n      v_path := 'sin_decidir'; v_q := 'a_nombre_de';\n      v_reason := format(case when v_nombre is null then '%s no dice a nombre de quién va.'\n                              else '%s va a nombre de «%s», y Folvy no sabe quién es.' end,\n                         case v_tipo when 'albaran' then 'El albarán' when 'factura' then 'La factura'\n                                     when 'albaran_factura' then 'El albarán-factura' else 'El documento' end,\n                         v_nombre);\n      v_qd := jsonb_build_object('nombre', v_nombre, 'nombre_norm', public.compras_nombre_norm(v_nombre),\n        -- Candidatos para contestar: las empresas de la cuenta y los proveedores\n        -- que liquidan. Primero el que empieza por la misma palabra: ordena, no decide.\n        'candidatos', (select coalesce(jsonb_agg(x order by x->>'orden', x->>'nombre'), '[]'::jsonb) from (\n          select jsonb_build_object('tipo', 'empresa', 'id', c.id, 'nombre', coalesce(c.legal_name, c.trade_name),\n                   'orden', case when split_part(public.compras_nombre_norm(coalesce(c.legal_name, c.trade_name)), ' ', 1) = split_part(public.compras_nombre_norm(v_nombre), ' ', 1) then '0' else '1' end) x\n            from company c where c.account_id = g.account_id and c.is_active\n          union all\n          select jsonb_build_object('tipo', 'proveedor', 'id', p.id, 'nombre', p.name,\n                   'orden', case when split_part(public.compras_nombre_norm(p.name), ' ', 1) = split_part(public.compras_nombre_norm(v_nombre), ' ', 1) then '0' else '1' end)\n            from supplier p where p.account_id = g.account_id and p.archived_at is null\n             and (p.invoicing_mode = 'monthly_settlement' or p.id = g.supplier_id)) y));\n    end if;\n  end if;\n\n  return jsonb_build_object('path', v_path, 'supplier_id', v_sup, 'company_id', v_company, 'doc_type', v_tipo,\n    'bill_to_name', v_nombre, 'bill_to_tax_id', v_nif, 'bill_to_how', v_how,\n    'question', v_q, 'question_detail', v_qd, 'reason', v_reason);\nend $function$\n	eb9e430fc2a97da0ff1548767f52e1c2	2026-10-30 08:34:55.888432+00
public._documento_trabajador_puede(text,boolean)	20261027T1905_l1a_fichar_en_el_servidor	CREATE OR REPLACE FUNCTION public._documento_trabajador_puede(p_name text, p_escribir boolean)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_partes text[] := storage.foldername(p_name); v_uno text; v_dos text; v_emp uuid; v_cuenta uuid;\nbegin\n  v_uno := v_partes[1]; v_dos := v_partes[2];\n  if v_uno = '_inbox' then\n    if v_dos is null or v_dos !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return public.current_user_is_admin(); end if;\n    v_cuenta := v_dos::uuid;\n    return case when p_escribir then public.current_user_is_admin_of(v_cuenta) else public.current_user_is_admin_or_manager_of(v_cuenta) end;\n  end if;\n  if v_uno is null or v_uno !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return public.current_user_is_admin(); end if;\n  v_emp := v_uno::uuid;\n  select e.account_id into v_cuenta from public.employees e where e.id = v_emp;\n  if v_cuenta is null then return public.current_user_is_admin(); end if;\n  if p_escribir then return public.current_user_is_admin_of(v_cuenta); end if;\n  return public.current_user_is_admin_or_manager_of(v_cuenta) or public.current_user_is_employee(v_emp, v_cuenta);\nend $function$\n	a0009aaf359276f22ad2c82c6f2858f0	2026-10-28 05:46:23.932303+00
public._f01_alta_marca(uuid,uuid,text,text,boolean,text,boolean,uuid,text)	20261028T0650_f01b_alta_sin_empleado	CREATE OR REPLACE FUNCTION public._f01_alta_marca(p_account uuid, p_org uuid, p_nombre_last text, p_nombre text, p_propia boolean, p_socio text, p_ensayo boolean, p_quien uuid, p_quien_nombre text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_last    text := btrim(coalesce(p_nombre_last, ''));\n  v_nombre  text := btrim(coalesce(nullif(btrim(p_nombre), ''), p_nombre_last));\n  v_socio   text := nullif(btrim(coalesce(p_socio, '')), '');\n  v_brand   uuid;\n  v_nueva   boolean := false;\n  v_slug    text;\n  v_n       integer := 1;\n  v_vinc    jsonb;\n  v_carta   jsonb;\n  v_ventas  jsonb;\nbegin\n  if v_last = '' then raise exception 'Falta la marca de Last.' using errcode = '22023'; end if;\n  if v_nombre = '' then raise exception 'Falta el nombre de la marca.' using errcode = '22023'; end if;\n  if p_propia is null then raise exception 'Falta decir si la marca es tuya o cedida.' using errcode = '22023'; end if;\n  if not p_propia and v_socio is null then raise exception 'Una marca cedida necesita su socio.' using errcode = '22023'; end if;\n  if not exists (select 1 from public.external_integration ei where ei.account_id = p_account and ei.source = 'lastapp'\n                  and ei.external_org_id = p_org and ei.is_active) then\n    raise exception 'Esa cuenta de Last no está conectada.' using errcode = 'P0002';\n  end if;\n  if not exists (select 1 from public._f01_filas(p_account, p_org, v_last)) then\n    raise exception 'La marca «%» ya no está en las cartas de Last.', v_last using errcode = 'P0002';\n  end if;\n\n  -- La marca: la del alta, la vinculada o la que se llama igual; si no hay, una nueva.\n  v_brand := coalesce(public._f01_marca_vinculada(p_account, p_org, v_last), public._f01_marca_por_nombre(p_account, v_nombre),\n                      public._f01_marca_por_nombre(p_account, v_last));\n  if v_brand is null then\n    v_nueva := true;\n    if not p_ensayo then\n      v_slug := coalesce(nullif(btrim(regexp_replace(lower(public.unaccent(v_nombre)), '[^a-z0-9]+', '-', 'g'), '-'), ''), 'marca');\n      while exists (select 1 from public.brand b where b.account_id = p_account and b.slug = case when v_n = 1 then v_slug else v_slug || '-' || v_n end) loop\n        v_n := v_n + 1;\n      end loop;\n      insert into public.brand (account_id, name, slug, ownership_type, is_active, catalog_source, created_by, created_by_name)\n      values (p_account, v_nombre, case when v_n = 1 then v_slug else v_slug || '-' || v_n end,\n              case when p_propia then 'own' else 'licensed' end, true, 'pos', p_quien, p_quien_nombre)\n      returning id into v_brand;\n    end if;\n  elsif not p_ensayo then\n    update public.brand set ownership_type = case when p_propia then 'own' else 'licensed' end, is_active = true, updated_at = now()\n     where id = v_brand and (ownership_type is distinct from case when p_propia then 'own' else 'licensed' end or not is_active);\n  end if;\n\n  if not p_ensayo then\n    -- De quién es: el socio de una cedida, en su ficha (el porcentaje, cuando se sepa).\n    if not p_propia then\n      insert into public.brand_licensing_agreement (account_id, brand_id, owner_name, revenue_share_pct, is_active, created_by, created_by_name)\n      values (p_account, v_brand, v_socio, null, true, p_quien, p_quien_nombre)\n      on conflict (brand_id) do update set owner_name = excluded.owner_name, is_active = true, archived_at = null, updated_at = now();\n    end if;\n    -- Darla de alta es usarla: si estaba entre las ocultas, deja de estarlo.\n    delete from public.external_brand_oculta\n     where account_id = p_account and source = 'lastapp' and external_org_id = p_org and external_brand_name = v_last;\n    insert into public.external_brand_alta (account_id, source, external_org_id, external_brand_name, brand_id, created_by, created_by_name)\n    values (p_account, 'lastapp', p_org, v_last, v_brand, p_quien, p_quien_nombre)\n    on conflict (account_id, source, external_org_id, external_brand_name) do update set brand_id = excluded.brand_id;\n  end if;\n\n  -- En ensayo con marca nueva, v_brand es null: se lee igual (nada de la marca existe todavía).\n  v_vinc  := public._f01_vincular(p_account, v_brand, p_org, v_last, p_ensayo, p_quien_nombre);\n  v_carta := public._f01_sembrar_marca(p_account, v_brand, p_org, v_last, p_ensayo, p_quien_nombre);\n  v_ventas := case when p_ensayo then null else public._f01_recolocar(p_account, v_brand, p_org, v_last) end;\n\n  return jsonb_build_object(\n    'brand_id', v_brand, 'nombre', v_nombre, 'nueva', v_nueva, 'propia', p_propia, 'socio', case when p_propia then null else v_socio end,\n    'ensayo', p_ensayo, 'locales', coalesce(v_vinc->'locales', '[]'::jsonb), 'canales', coalesce(v_vinc->'canales', '[]'::jsonb),\n    'vinculos_nuevos', coalesce((v_vinc->>'vinculos_nuevos')::integer, 0), 'vinculos_de_otra_marca', coalesce(v_vinc->'vinculos_de_otra_marca', '[]'::jsonb),\n    'carta', v_carta, 'ventas', v_ventas);\nend $function$\n	3c4e68e2a2b4f3a893d862a19885f1da	2026-10-28 07:35:30.83644+00
public._informe_registro_jornada(uuid,date,date,boolean,boolean)	20261029T0733_l1a_informe_origen	CREATE OR REPLACE FUNCTION public._informe_registro_jornada(p_employee_id uuid, p_desde date, p_hasta date, p_con_dni boolean, p_motivos_baja boolean)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  e public.employees; v_acct public.accounts; v_local text;\n  v_ini timestamptz := (p_desde::timestamp at time zone 'Europe/Madrid');\n  v_fin timestamptz := ((p_hasta + 1)::timestamp at time zone 'Europe/Madrid') + interval '16 hours';\nbegin\n  select * into e from public.employees where id = p_employee_id;\n  if e.id is null then raise exception 'PERSONA_NO_EXISTE' using errcode = '22023'; end if;\n  select * into v_acct from public.accounts where id = e.account_id;\n  select name into v_local from public.locations where id = e.location_id;\n  return jsonb_build_object(\n    'generado_at', now(),\n    'periodo', jsonb_build_object('desde', p_desde, 'hasta', p_hasta),\n    'empresa', jsonb_build_object('nombre', coalesce(nullif(v_acct.legal_name, ''), v_acct.name), 'cif', v_acct.cif),\n    'persona', jsonb_build_object(\n      'id', e.id, 'nombre', e.name, 'dni', case when p_con_dni then e.dni end,\n      'puesto', e.position, 'local', v_local, 'tipo_contrato', e.contract_type,\n      'horas_semana', coalesce(e.contracted_hours_week, e.weekly_hours), 'alta', e.start_date),\n    'marcas', coalesce((\n      select jsonb_agg(jsonb_build_object(\n               'id', ce.id, 'tipo', ce.type, 'hora', coalesce(ce.real_datetime, ce.datetime),\n               'declarada', ce.declared_at, 'llegada', ce.created_at, 'origen', ce.source,\n               'local', l.name, 'distancia_m', ce.distance_m, 'dentro_del_radio', ce.within_radius,\n               'anulada', coalesce(ce.voided, false))\n             order by coalesce(ce.real_datetime, ce.datetime), ce.id)\n        from public.clock_entries ce\n        left join public.locations l on l.id = ce.location_id_at_clock\n       where ce.employee_id = e.id\n         and coalesce(ce.real_datetime, ce.datetime) >= v_ini\n         and coalesce(ce.real_datetime, ce.datetime) < v_fin), '[]'::jsonb),\n    'cambios', coalesce((\n      select jsonb_agg(jsonb_build_object(\n               'id', a.id, 'marca', a.clock_entry_id, 'accion', a.action, 'cuando', a.created_at,\n               'quien', coalesce(nullif(up.display_name, ''), nullif(a.actor_label, ''), case when a.actor_user_id is null then 'el sistema' end),\n               'papel', up.role,\n               'es_la_persona', (up.employee_id is not null and up.employee_id = e.id),\n               'motivo', a.reason, 'antes', a.before, 'despues', a.after,\n               'conformidad', a.conformidad, 'conformidad_at', a.conformidad_at, 'conformidad_nota', a.conformidad_nota,\n               'peticion', case when r.id is null then null else jsonb_build_object(\n                  'pedida_at', r.created_at, 'motivo', r.reason, 'tipo', r.kind) end)\n             order by a.created_at, a.id)\n        from public.clock_entry_audit a\n        left join lateral (\n          select u.display_name, u.role, u.employee_id from public.user_profiles u\n           where u.user_id = a.actor_user_id and u.account_id = e.account_id\n           order by u.active desc limit 1) up on true\n        left join public.clock_correction_request r on r.id = a.peticion_id\n       where a.employee_id = e.id\n         and a.action in ('create_manual', 'edit', 'void', 'restore')\n         and a.clock_entry_id in (\n           select ce.id from public.clock_entries ce\n            where ce.employee_id = e.id\n              and coalesce(ce.real_datetime, ce.datetime) >= v_ini\n              and coalesce(ce.real_datetime, ce.datetime) < v_fin)), '[]'::jsonb),\n    'firmas', coalesce((\n      select jsonb_agg(jsonb_build_object(\n               'mes', f.mes, 'firmado_at', f.firmado_at, 'invalidada_at', f.invalidada_at,\n               'invalidada_motivo', f.invalidada_motivo,\n               'vigente', f.invalidada_at is null\n                          and f.huella = public._huella_registro_mes(e.id, f.mes))\n             order by f.mes, f.firmado_at)\n        from public.registro_jornada_firma f\n       where f.employee_id = e.id\n         and f.mes between date_trunc('month', p_desde)::date and p_hasta), '[]'::jsonb),\n    'ausencias', coalesce((\n      select jsonb_agg(jsonb_build_object(\n               'desde', v.start_date, 'hasta', v.end_date,\n               'tipo', case when v.type = 'baja_medica' and not p_motivos_baja then 'ausente' else v.type end)\n             order by v.start_date)\n        from public.vacations v\n       where v.employee_id = e.id and v.status = 'aprobada'\n         and v.start_date <= p_hasta and v.end_date >= p_desde), '[]'::jsonb),\n    'festivos', coalesce((\n      select jsonb_agg(jsonb_build_object('dia', h.holiday_date, 'nombre', h.name) order by h.holiday_date)\n        from public.holiday_calendar h\n       where (h.account_id is null or h.account_id = e.account_id)\n         and h.holiday_date between p_desde and p_hasta), '[]'::jsonb)\n  );\nend $function$\n	cc695df7b8a8773d2c00e747011ee426	2026-10-29 08:33:27.637644+00
public._journal_entry_proponer(uuid,jsonb,jsonb,jsonb,text,uuid)	20261027T1350_v04_recibida_fecha_entrada	CREATE OR REPLACE FUNCTION public._journal_entry_proponer(p_company uuid, p_entry jsonb, p_lines jsonb, p_summary jsonb, p_quien_nombre text, p_quien uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_cuenta uuid; v_fecha date := (p_entry->>'fecha')::date; v_tipo text := p_entry->>'source_type';\n  v_origen uuid := nullif(p_entry->>'source_id', '')::uuid; v_clave text; v_y uuid; v_id uuid; v_l jsonb; v_pos int := 0;\n  v_cta uuid; v_resumen uuid; v_existente uuid;\n  v_unidad text := nullif(p_summary->>'unit_key', ''); v_dia_clave text;\nbegin\n  select account_id into v_cuenta from public.company where id = p_company;\n  if v_cuenta is null then\n    raise exception 'La empresa % no existe.', p_company using errcode = '23514';\n  end if;\n  if v_tipo = 'sales_day' then\n    v_dia_clave := (p_summary->>'location_id') || ':' || (p_summary->>'sales_day');\n    v_clave := v_dia_clave || coalesce(':' || v_unidad, '');\n    -- El botón y el cierre del día pueden llegar a la vez al mismo día: el\n    -- cerrojo es del día y el local, también con unidades (C04b R5), para que\n    -- un asiento del día entero y uno de una unidad no se crucen.\n    perform pg_advisory_xact_lock(hashtextextended('sales_day:' || p_company::text || ':' || v_dia_clave, 0));\n    -- C04b R5: con la regla por plataforma, el día entero ya no se propone.\n    -- Lo dice (regla 8) en vez de dejar un asiento al lado de los de cada\n    -- plataforma: así el front de antes no puede duplicar.\n    if v_unidad is null and exists (select 1 from public.conta_ventas_canal v where v.company_id = p_company) then\n      raise exception 'Las ventas se asientan ahora por plataforma, local y día, y las propone el cierre del día cada hora. Recarga la página.' using errcode = '23514';\n    end if;\n  else\n    v_clave := v_origen::text;\n  end if;\n  if v_clave is not null and exists (select 1 from public.journal_dismissal d where d.company_id = p_company and d.source_type = v_tipo\n                                        and d.source_key in (v_clave, coalesce(v_dia_clave, v_clave))) then\n    return jsonb_build_object('descartada', true);\n  end if;\n\n  if v_tipo = 'sales_day' then\n    -- Un día ya asentado entero (a la antigua) no se vuelve a asentar por unidades.\n    if v_unidad is not null then\n      select s.entry_id into v_existente from public.sales_day_summary s join public.journal_entry e on e.id = s.entry_id\n       where s.company_id = p_company and s.location_id = (p_summary->>'location_id')::uuid and s.sales_day = (p_summary->>'sales_day')::date\n         and s.unit_key is null and e.status in ('propuesto', 'borrador', 'validado');\n      if v_existente is not null then return jsonb_build_object('id', v_existente, 'existente', true); end if;\n    end if;\n    select s.id, s.entry_id into v_resumen, v_existente from public.sales_day_summary s\n     where s.company_id = p_company and s.location_id = (p_summary->>'location_id')::uuid and s.sales_day = (p_summary->>'sales_day')::date\n       and s.unit_key is not distinct from v_unidad;\n    if v_existente is not null and exists (select 1 from public.journal_entry e where e.id = v_existente and e.status in ('propuesto', 'borrador', 'validado')) then\n      return jsonb_build_object('id', v_existente, 'existente', true);\n    end if;\n    if v_resumen is null then\n      insert into public.sales_day_summary (account_id, company_id, location_id, sales_day, unit_key, channel_id, brand_id, tickets_count, total, by_rate, by_channel, by_brand,\n                                            first_invoice, last_invoice, detail_hash, sale_ids, base_calculated, created_by)\n      values (v_cuenta, p_company, (p_summary->>'location_id')::uuid, (p_summary->>'sales_day')::date,\n              v_unidad, nullif(p_summary->>'channel_id', '')::uuid, nullif(p_summary->>'brand_id', '')::uuid, (p_summary->>'tickets_count')::int,\n              (p_summary->>'total')::numeric, coalesce(p_summary->'by_rate', '[]'), coalesce(p_summary->'by_channel', '[]'), coalesce(p_summary->'by_brand', '[]'),\n              p_summary->>'first_invoice', p_summary->>'last_invoice', p_summary->>'detail_hash',\n              coalesce((select array_agg(x::uuid) from jsonb_array_elements_text(p_summary->'sale_ids') x), '{}'),\n              coalesce((p_summary->>'base_calculated')::boolean, false), p_quien)\n      returning id into v_resumen;\n    else\n      -- Un resumen sin asiento vivo (el del 09/10 de Carabanchel, de antes del\n      -- cierre del día) se rehace entero con el día de ahora: no se duplica.\n      update public.sales_day_summary set tickets_count = (p_summary->>'tickets_count')::int, total = (p_summary->>'total')::numeric,\n             by_rate = coalesce(p_summary->'by_rate', '[]'), by_channel = coalesce(p_summary->'by_channel', '[]'), by_brand = coalesce(p_summary->'by_brand', '[]'),\n             detail_hash = p_summary->>'detail_hash',\n             sale_ids = coalesce((select array_agg(x::uuid) from jsonb_array_elements_text(p_summary->'sale_ids') x), '{}'),\n             base_calculated = coalesce((p_summary->>'base_calculated')::boolean, false), entry_id = null\n       where id = v_resumen;\n    end if;\n    v_origen := v_resumen;\n  elsif v_origen is not null then\n    select id into v_existente from public.journal_entry\n     where company_id = p_company and source_type = v_tipo and source_id = v_origen and status in ('propuesto', 'borrador', 'validado');\n    if v_existente is not null then return jsonb_build_object('id', v_existente, 'existente', true); end if;\n  end if;\n\n  -- V04 · candado del IVA (1233): una recibida que llega a un periodo cuyo IVA\n  -- ya está presentado se asienta en el primer día abierto, sin preguntar; una\n  -- expedida no se mueve: para. La fecha de la factura no se toca.\n  p_entry := public._conta_iva_ajustar_propuesta(p_company, p_entry, p_lines);\n  v_fecha := (p_entry->>'fecha')::date;\n\n  select id into v_y from public.fiscal_year where company_id = p_company and v_fecha between starts_on and ends_on;\n  if v_y is null then raise exception 'No hay ejercicio para el %.', to_char(v_fecha, 'DD/MM/YYYY') using errcode = '23514'; end if;\n\n  insert into public.journal_entry (account_id, company_id, fiscal_year_id, series, entry_date, concept, source_type, source_id, status,\n                                    confidence, reason, reasons, party_id, document_ref, document_date, created_by, created_by_name)\n  values (v_cuenta, p_company, v_y, (p_entry->>'series')::smallint, v_fecha, p_entry->>'concepto', v_tipo, v_origen, 'propuesto',\n          p_entry->>'confianza', p_entry->>'porque', coalesce(p_entry->'razones', '[]'), nullif(p_entry->>'party_id', '')::uuid,\n          p_entry->>'documento', nullif(p_entry->>'fecha_documento', '')::date, p_quien, coalesce(p_quien_nombre, 'Folvy'))\n  returning id into v_id;\n\n  for v_l in select * from jsonb_array_elements(p_lines) loop\n    v_pos := v_pos + 1;\n    select id into v_cta from public.company_account where company_id = p_company and code = v_l->>'cuenta';\n    if v_cta is null then raise exception 'La cuenta % no está en el plan de la empresa.', v_l->>'cuenta' using errcode = '23514'; end if;\n    insert into public.journal_line (account_id, company_id, entry_id, position, company_account_id, debit, credit, concept, location_id, is_common,\n                                     brand_id, party_id, document_ref, tax_rate_id, tax_base, vat_book, vat_deductible, tax_documents,\n                                     withholding_rate_id, withholding_base, withholding_model)\n    values (v_cuenta, p_company, v_id, v_pos, v_cta, coalesce((v_l->>'debe')::numeric, 0), coalesce((v_l->>'haber')::numeric, 0), v_l->>'concepto',\n            nullif(v_l->>'local_id', '')::uuid, coalesce((v_l->>'comun')::boolean, false), nullif(v_l->>'marca_id', '')::uuid,\n            nullif(v_l->>'tercero_id', '')::uuid, v_l->>'documento',\n            nullif(v_l->'iva'->>'tipo_id', '')::uuid, (v_l->'iva'->>'base')::numeric, v_l->'iva'->>'libro', v_l->'iva'->>'deducible',\n            coalesce((v_l->'iva'->>'facturas')::int, 1),\n            nullif(v_l->'retencion'->>'tipo_id', '')::uuid, (v_l->'retencion'->>'base')::numeric, v_l->'retencion'->>'modelo');\n  end loop;\n  if v_resumen is not null then update public.sales_day_summary set entry_id = v_id where id = v_resumen; end if;\n  return jsonb_strip_nulls(jsonb_build_object('id', v_id, 'existente', false, 'aviso', p_entry->>'aviso'));\nend $function$\n	7d7680b983cd2d5fd846fd2890ed139d	2026-10-27 14:29:44.093725+00
