mmary->>'brand_id', '')::uuid, (p_summary->>'tickets_count')::int,\n              (p_summary->>'total')::numeric, coalesce(p_summary->'by_rate', '[]'), coalesce(p_summary->'by_channel', '[]'), coalesce(p_summary->'by_brand', '[]'),\n              p_summary->>'first_invoice', p_summary->>'last_invoice', p_summary->>'detail_hash',\n              coalesce((select array_agg(x::uuid) from jsonb_array_elements_text(p_summary->'sale_ids') x), '{}'),\n              coalesce((p_summary->>'base_calculated')::boolean, false), p_quien)\n      returning id into v_resumen;\n    else\n      -- Un resumen sin asiento vivo (el del 09/10 de Carabanchel, de antes del\n      -- cierre del día) se rehace entero con el día de ahora: no se duplica.\n      update public.sales_day_summary set tickets_count = (p_summary->>'tickets_count')::int, total = (p_summary->>'total')::numeric,\n             by_rate = coalesce(p_summary->'by_rate', '[]'), by_channel = coalesce(p_summary->'by_channel', '[]'), by_brand = coalesce(p_summary->'by_brand', '[]'),\n             detail_hash = p_summary->>'detail_hash',\n             sale_ids = coalesce((select array_agg(x::uuid) from jsonb_array_elements_text(p_summary->'sale_ids') x), '{}'),\n             base_calculated = coalesce((p_summary->>'base_calculated')::boolean, false), entry_id = null\n       where id = v_resumen;\n    end if;\n    v_origen := v_resumen;\n  elsif v_origen is not null then\n    select id into v_existente from public.journal_entry\n     where company_id = p_company and source_type = v_tipo and source_id = v_origen and status in ('propuesto', 'borrador', 'validado');\n    if v_existente is not null then return jsonb_build_object('id', v_existente, 'existente', true); end if;\n  end if;\n\n  select id into v_y from public.fiscal_year where company_id = p_company and v_fecha between starts_on and ends_on;\n  if v_y is null then raise exception 'No hay ejercicio para el %.', to_char(v_fecha, 'DD/MM/YYYY') using errcode = '23514'; end if;\n\n  insert into public.journal_entry (account_id, company_id, fiscal_year_id, series, entry_date, concept, source_type, source_id, status,\n                                    confidence, reason, reasons, party_id, document_ref, document_date, created_by, created_by_name)\n  values (v_cuenta, p_company, v_y, (p_entry->>'series')::smallint, v_fecha, p_entry->>'concepto', v_tipo, v_origen, 'propuesto',\n          p_entry->>'confianza', p_entry->>'porque', coalesce(p_entry->'razones', '[]'), nullif(p_entry->>'party_id', '')::uuid,\n          p_entry->>'documento', nullif(p_entry->>'fecha_documento', '')::date, p_quien, coalesce(p_quien_nombre, 'Folvy'))\n  returning id into v_id;\n\n  for v_l in select * from jsonb_array_elements(p_lines) loop\n    v_pos := v_pos + 1;\n    select id into v_cta from public.company_account where company_id = p_company and code = v_l->>'cuenta';\n    if v_cta is null then raise exception 'La cuenta % no está en el plan de la empresa.', v_l->>'cuenta' using errcode = '23514'; end if;\n    insert into public.journal_line (account_id, company_id, entry_id, position, company_account_id, debit, credit, concept, location_id, is_common,\n                                     brand_id, party_id, document_ref, tax_rate_id, tax_base, vat_book, vat_deductible, tax_documents,\n                                     withholding_rate_id, withholding_base, withholding_model)\n    values (v_cuenta, p_company, v_id, v_pos, v_cta, coalesce((v_l->>'debe')::numeric, 0), coalesce((v_l->>'haber')::numeric, 0), v_l->>'concepto',\n            nullif(v_l->>'local_id', '')::uuid, coalesce((v_l->>'comun')::boolean, false), nullif(v_l->>'marca_id', '')::uuid,\n            nullif(v_l->>'tercero_id', '')::uuid, v_l->>'documento',\n            nullif(v_l->'iva'->>'tipo_id', '')::uuid, (v_l->'iva'->>'base')::numeric, v_l->'iva'->>'libro', v_l->'iva'->>'deducible',\n            coalesce((v_l->'iva'->>'facturas')::int, 1),\n            nullif(v_l->'retencion'->>'tipo_id', '')::uuid, (v_l->'retencion'->>'base')::numeric, v_l->'retencion'->>'modelo');\n  end loop;\n  if v_resumen is not null then update public.sales_day_summary set entry_id = v_id where id = v_resumen; end if;\n  return jsonb_build_object('id', v_id, 'existente', false);\nend $function$\n	7078efe93262f038dc888e1ca1c1cdd7	2026-10-27 12:48:15.02106+00
public._pc01e2b_iban_de_la_factura()	20261028T1305_s01b_iban_no_se_pone_solo	CREATE OR REPLACE FUNCTION public._pc01e2b_iban_de_la_factura()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_s public.supplier; v_leido text := public._pc01e2_iban(new.read_iban); v_ficha text;\nbegin\n  if tg_op = 'UPDATE' and new.supplier_id is not distinct from old.supplier_id and v_leido is not distinct from public._pc01e2_iban(old.read_iban) then return null; end if;\n  if new.status in ('anulada', 'descartada', 'pagada') or coalesce(new.payment_method, 'transfer') <> 'transfer' then return null; end if;\n  select * into v_s from public.supplier where id = new.supplier_id and account_id = new.account_id for update;\n  if v_s.id is null or v_s.archived_at is not null then return null; end if;\n  -- Domiciliado, con tarjeta, al contado o prepago en su ficha, y la factura no dice otra cosa: no se le paga por transferencia.\n  if new.payment_method is null and coalesce(v_s.payment_method, 'transfer') <> 'transfer' then return null; end if;\n  v_ficha := public._pc01e2_iban(v_s.iban);\n  if v_ficha is null then\n    update public.supplier set iban = v_leido, iban_set_at = now(), iban_set_by = null, iban_set_by_name = 'Sumied',\n           iban_unconfirmed_invoice_id = new.id, updated_at = now()\n     where id = v_s.id;\n    insert into public.document_activity (account_id, company_id, inbox_id, supplier_invoice_id, actor, action, text, detail)\n    values (new.account_id, new.company_id, new.inbox_id, new.id, 'folvy', 'corregida',\n            format('%s no tenía IBAN: le pongo el de esta factura (···· %s), sin confirmar. Se confirma la primera vez que se le paga por remesa.', v_s.name, right(v_leido, 4)),\n            jsonb_build_object('iban_puesto', true, 'iban4', right(v_leido, 4), 'supplier_id', v_s.id));\n  elsif v_ficha <> v_leido and new.iban_decision is null then\n    insert into public.document_activity (account_id, company_id, inbox_id, supplier_invoice_id, actor, action, text, detail)\n    values (new.account_id, new.company_id, new.inbox_id, new.id, 'folvy', 'leida',\n            format('Esta factura trae otro IBAN (···· %s) que el de la ficha de %s (···· %s). No se paga hasta que alguien decida si es el nuevo.', right(v_leido, 4), v_s.name, right(v_ficha, 4)),\n            jsonb_build_object('iban_distinto', true, 'iban4', right(v_leido, 4), 'ficha4', right(v_ficha, 4), 'supplier_id', v_s.id));\n  end if;\n  return null;\nend $function$\n	38e2b4019a95d85e923286c4cb5ab983	2026-10-28 14:42:23.835052+00
public._s01_asiento_cobro(uuid,text)	20261028T0735_s01_enlace_validado	CREATE OR REPLACE FUNCTION public._s01_asiento_cobro(p_payment uuid, p_proveedor text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare p public.customer_invoice_payment; v public.customer_invoice; v_cli text; v_pas text; v_res jsonb; v_entry uuid; v_nombre text; v_concepto text;\nbegin\n  select * into p from public.customer_invoice_payment where id = p_payment for update;\n  if p.id is null then return jsonb_build_object('asiento', null, 'motivo', 'el cobro no existe'); end if;\n  if p.entry_id is not null and exists (select 1 from public.journal_entry where id = p.entry_id and status in ('propuesto', 'borrador', 'validado')) then\n    return jsonb_build_object('asiento', p.entry_id, 'motivo', null, 'ya', true);\n  end if;\n  select * into v from public.customer_invoice where id = p.invoice_id;\n  select coalesce(pa.name, v.customer->>'nombre') into v_nombre from public.party pa where pa.id = v.party_id;\n  v_nombre := coalesce(v_nombre, v.customer->>'nombre', 'el cliente');\n  v_cli := public._pc01e3_cuenta_cliente(p.company_id, v.party_id);\n  if v_cli is null then return jsonb_build_object('asiento', null, 'motivo', format('%s no tiene su cuenta de cliente (430)', v_nombre)); end if;\n  v_pas := public._s01_cuenta_pasarela(p.company_id, p_proveedor);\n  if v_pas is null then return jsonb_build_object('asiento', null, 'motivo', 'la empresa aún no tiene el plan contable activado'); end if;\n  v_concepto := format('Cobro %s · %s · %s', case p_proveedor when 'redsys' then 'TPV' else 'Stripe' end, v_nombre, coalesce(v.number_text, 'sin número'));\n  v_res := public._journal_entry_proponer(p.company_id,\n    jsonb_build_object('fecha', p.paid_on, 'series', (public._bank_ajustes(p.company_id)).treasury_series, 'concepto', v_concepto,\n                       'source_type', 'customer_payment', 'source_id', p.id, 'confianza', 'seguro',\n                       'porque', format('El cliente pagó %s con %s por el enlace de pago, y %s lo confirmó: ya no debe; queda por abonar en el banco.',\n                                        public.conta_euros_exactos(p.amount), case when p.method = 'bizum' then 'Bizum' else 'tarjeta' end,\n                                        case p_proveedor when 'redsys' then 'el banco' else 'Stripe' end),\n                       'razones', '[]'::jsonb, 'party_id', v.party_id, 'documento', v.number_text),\n    jsonb_build_array(\n      jsonb_build_object('cuenta', v_pas, 'debe', p.amount, 'haber', 0, 'concepto', v_concepto, 'comun', true),\n      jsonb_build_object('cuenta', v_cli, 'debe', 0, 'haber', p.amount, 'tercero_id', v.party_id, 'concepto', v_concepto, 'comun', true)),\n    '{}'::jsonb, 'Sumied', null);\n  v_entry := (v_res->>'id')::uuid;\n  update public.customer_invoice_payment set entry_id = v_entry where id = p.id;\n  return jsonb_build_object('asiento', v_entry, 'motivo', null, 'cuenta', v_pas);\nend $function$\n	055494f1099db2ce5abdcd1022907b7e	2026-10-28 11:33:52.724436+00
public._ticket_invoice_number(uuid,uuid,uuid,text,text,text,timestamptz)	20261027T0741_v04_tique_verifactu	CREATE OR REPLACE FUNCTION public._ticket_invoice_number(p_account uuid, p_location uuid, p_sale uuid, p_code text, p_issuer_name text, p_issuer_tax_id text, p_at timestamp with time zone DEFAULT now())\n RETURNS ticket_invoice\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_t public.ticket_invoice; v_s public.ticket_invoice_series; v_year integer;\nbegin\n  if p_account is null or p_location is null or p_sale is null or p_code is null then\n    raise exception 'Faltan datos para numerar el tique.' using errcode = '22023';\n  end if;\n  perform pg_advisory_xact_lock(hashtextextended('ticket_invoice:' || p_account::text || ':' || p_sale::text, 0));\n  select * into v_t from public.ticket_invoice where account_id = p_account and sale_id = p_sale and kind = 'F';\n  if v_t.id is not null then return v_t; end if;\n  v_year := extract(year from (p_at at time zone 'Europe/Madrid'))::integer;\n  insert into public.ticket_invoice_series as s (account_id, location_id, code, year, kind, last_number)\n  values (p_account, p_location, p_code, v_year, 'F', 1)\n  on conflict (account_id, location_id, year, kind) do update set last_number = s.last_number + 1, updated_at = now()\n  returning * into v_s;\n  insert into public.ticket_invoice (account_id, sale_id, location_id, series_id, kind, number, number_text, issued_at, issuer_name, issuer_tax_id)\n  values (p_account, p_sale, p_location, v_s.id, 'F', v_s.last_number,\n          public._ticket_invoice_text(v_s.code, v_s.year, 'F', v_s.last_number), p_at, p_issuer_name, p_issuer_tax_id)\n  returning * into v_t;\n  return v_t;\nend $function$\n	6e1408825f8e320ea7ac13f1e656c5f3	2026-10-27 09:45:29.27972+00
public.add_manual_clock_entry(uuid,text,timestamp with time zone,text,text,boolean)	20261027T1905_l1a_fichar_en_el_servidor	CREATE OR REPLACE FUNCTION public.add_manual_clock_entry(p_employee_id uuid, p_type text, p_datetime timestamp with time zone, p_reason text, p_actor_label text DEFAULT NULL::text, p_force boolean DEFAULT false)\n RETURNS clock_entries\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_acct   uuid;\n  v_row    public.clock_entries;\n  v_loc    uuid;\n  v_prev   text;\n  v_prevat timestamptz;\n  v_reason text := p_reason;\nbegin\n  if coalesce(trim(p_reason),'') = '' then raise exception 'MOTIVO_OBLIGATORIO'; end if;\n  if p_type not in ('entrada','salida') then raise exception 'TIPO_INVALIDO'; end if;\n  v_acct := public._account_of_employee(p_employee_id);\n  if v_acct is null or not public.current_user_is_admin_of(v_acct) then raise exception 'NO_AUTORIZADO'; end if;\n  select location_id into v_loc from public.employees where id = p_employee_id;\n\n  -- Estado EN EL MOMENTO de p_datetime, no ahora: un arreglo historico se\n  -- valida contra el momento que corrige.\n  select ce.type, coalesce(ce.real_datetime, ce.datetime)\n    into v_prev, v_prevat\n  from public.clock_entries ce\n  where ce.employee_id = p_employee_id\n    and coalesce(ce.voided,false) = false\n    and coalesce(ce.real_datetime, ce.datetime) < p_datetime\n  order by coalesce(ce.real_datetime, ce.datetime) desc\n  limit 1;\n\n  if not p_force then\n    if p_type = 'entrada' and v_prev in ('entrada','pausa_inicio','pausa_fin') then\n      raise exception 'YA_ESTA_FICHADO: la persona ya tenia una % sin cerrar a las %. '\n                      'Para dos entradas seguidas hay que forzar con motivo explicito.',\n                      v_prev, to_char(v_prevat at time zone 'Europe/Madrid','DD/MM HH24:MI');\n    end if;\n    if p_type = 'salida' and (v_prev is null or v_prev = 'salida') then\n      raise exception 'NO_ESTA_FICHADO: no hay ninguna entrada abierta antes de las %. '\n                      'Para cerrar sin apertura hay que forzar con motivo explicito.',\n                      to_char(p_datetime at time zone 'Europe/Madrid','DD/MM HH24:MI');\n    end if;\n  else\n    v_reason := 'FORZADO · ' || p_reason;\n  end if;\n\n  insert into public.clock_entries(employee_id, type, datetime, real_datetime, source, address, location_id_at_clock)\n  values (p_employee_id, p_type, p_datetime, p_datetime, 'manual',\n          'Manual · '||v_reason||coalesce(' · por '||p_actor_label,''), v_loc)\n  returning * into v_row;\n\n  insert into public.clock_entry_audit(\n    clock_entry_id, employee_id, account_id, action, actor_user_id, actor_label, reason, before, after)\n  values (v_row.id, p_employee_id, v_acct, 'create_manual', auth.uid(), p_actor_label, v_reason,\n          null, public._clock_snapshot(v_row));\n  return v_row;\nend $function$\n	f23f4443a66b4e5122a8fb2ab21aee43	2026-10-28 05:46:23.932303+00
public.conta_enlace_pago_cobrado(text,text,text,numeric,text,date)	20261027T2031_s01_enlace_con_redsys	CREATE OR REPLACE FUNCTION public.conta_enlace_pago_cobrado(p_sesion text, p_stripe text, p_pago_ref text, p_importe numeric, p_metodo text, p_fecha date)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare e public.conta_enlace_pago; v public.customer_invoice; v_queda numeric; v_apunta numeric; v_pago uuid; v_metodo text;\nbegin\n  select * into e from public.conta_enlace_pago where sesion = p_sesion for update;\n  if e.id is null then return jsonb_build_object('hecho', false, 'motivo', 'no_existe'); end if;\n  if e.status = 'pagado' then return jsonb_build_object('hecho', false, 'motivo', 'ya_cobrado'); end if;\n  if not exists (select 1 from public.conta_cobro_stripe where company_id = e.company_id and stripe_account_id = p_stripe) then\n    return jsonb_build_object('hecho', false, 'motivo', 'otra_cuenta');\n  end if;\n  select * into v from public.customer_invoice where id = e.invoice_id for update;\n  v_metodo := case when lower(coalesce(p_metodo, '')) = 'bizum' then 'bizum' else 'tarjeta' end;\n  v_queda := v.total - coalesce((select sum(amount) from public.customer_invoice_payment where invoice_id = v.id), 0);\n  v_apunta := least(coalesce(p_importe, 0), greatest(v_queda, 0));\n  if v_apunta > 0 then\n    insert into public.customer_invoice_payment (account_id, company_id, invoice_id, paid_on, amount, method, note, created_by_name)\n    values (v.account_id, v.company_id, v.id, coalesce(p_fecha, public.conta_hoy()), v_apunta, v_metodo,\n            'Enlace de pago (' || case when v_metodo = 'bizum' then 'Bizum' else 'tarjeta' end || ')', 'Sumied')\n    returning id into v_pago;\n  end if;\n  update public.conta_enlace_pago set status = 'pagado', pago_ref = p_pago_ref, metodo = v_metodo, importe = p_importe, pagado_at = now(), payment_id = v_pago\n   where id = e.id;\n  perform public._conta_venta_evento(v.id, 'cobro',\n    format('Cobro de %s con %s por el enlace de pago%s', public.conta_euros_exactos(p_importe), case when v_metodo = 'bizum' then 'Bizum' else 'tarjeta' end,\n      case when coalesce(p_importe, 0) > v_apunta then format(': se apuntan %s, lo que quedaba; el resto, %s, lo tiene Stripe y hay que devolverlo.',\n                                                       public.conta_euros_exactos(v_apunta), public.conta_euros_exactos(p_importe - v_apunta))\n           when v_queda - v_apunta < 0.005 then ': cobrada entera.' else format('; quedan %s.', public.conta_euros_exactos(v_queda - v_apunta)) end),\n    jsonb_build_object('importe', p_importe, 'apuntado', v_apunta, 'metodo', v_metodo, 'enlace', e.id), 'Sumied');\n  return jsonb_build_object('hecho', true, 'factura', v.id, 'apuntado', v_apunta, 'sobra', greatest(coalesce(p_importe, 0) - v_apunta, 0));\nend $function$\n	4dd9fbe6a57d8021b50be094702ce188	2026-10-28 05:27:04.450136+00
public.conta_enlace_pago_datos(text)	20261027T2031_s01_enlace_con_redsys	CREATE OR REPLACE FUNCTION public.conta_enlace_pago_datos(p_token text)\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select jsonb_build_object('enlace', e.id, 'estado', e.status, 'empresa_id', e.company_id, 'factura_id', e.invoice_id, 'factura', v.number_text, 'pendiente', c.pendiente,\n                            'empresa', coalesce(nullif(trim(co.trade_name), ''), co.legal_name), 'correo', nullif(lower(trim(v.email_to)), ''),\n                            'stripe', s.stripe_account_id, 'modo', s.modo, 'tarjeta', s.tarjeta, 'bizum', s.bizum)\n    from public.conta_enlace_pago e\n    join public.customer_invoice v on v.id = e.invoice_id\n    join public.conta_factura_cobro c on c.invoice_id = e.invoice_id\n    join public.company co on co.id = e.company_id\n    left join public.conta_cobro_stripe s on s.company_id = e.company_id\n   where e.token = p_token\n$function$\n	7a0ee871cd7cb4fbf912c510fd393f5f	2026-10-28 05:27:04.450136+00
public.conta_enlace_pago_para(uuid)	20261027T2031_s01_enlace_con_redsys	CREATE OR REPLACE FUNCTION public.conta_enlace_pago_para(p_invoice uuid)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v public.customer_invoice; c record; s public.conta_cobro_stripe; v_token text;\nbegin\n  select * into v from public.customer_invoice where id = p_invoice;\n  if v.id is null or v.status <> 'emitida' then return null; end if;\n  select * into c from public.conta_factura_cobro where invoice_id = p_invoice;\n  if c.invoice_id is null or c.de_plataforma or c.total <= 0 or c.pendiente < 0.005 then return null; end if;\n  select * into s from public.conta_cobro_stripe where company_id = v.company_id;\n  if s.company_id is null or s.tarjeta <> 'activo' then return null; end if;\n  select token into v_token from public.conta_enlace_pago where invoice_id = p_invoice and status = 'abierto';\n  if v_token is not null then return v_token; end if;\n  v_token := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');\n  insert into public.conta_enlace_pago (account_id, company_id, invoice_id, token) values (v.account_id, v.company_id, v.id, v_token);\n  perform public._conta_venta_evento(v.id, 'enlace_pago', 'Enlace de pago preparado (tarjeta' || case when s.bizum = 'activo' then ' y Bizum' else '' end || ').', null, 'Sumied');\n  return v_token;\nend $function$\n	93096ef1e158e97e64d4d20025514b9b	2026-10-28 05:27:04.450136+00
public.conta_enlace_pago_ver(text)	20261027T2031_s01_enlace_con_redsys	CREATE OR REPLACE FUNCTION public.conta_enlace_pago_ver(p_token text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare e public.conta_enlace_pago; v public.customer_invoice; c record; s public.conta_cobro_stripe; co public.company;\nbegin\n  if p_token is null or p_token !~ '^[0-9a-f]{64}$' then return jsonb_build_object('estado', 'no_existe'); end if;\n  select * into e from public.conta_enlace_pago where token = p_token;\n  if e.id is null then return jsonb_build_object('estado', 'no_existe'); end if;\n  select * into v from public.customer_invoice where id = e.invoice_id;\n  select * into c from public.conta_factura_cobro where invoice_id = e.invoice_id;\n  select * into s from public.conta_cobro_stripe where company_id = e.company_id;\n  select * into co from public.company where id = e.company_id;\n  if e.status = 'abierto' then\n    update public.conta_enlace_pago set aperturas = aperturas + 1, abierto_at = now() where id = e.id;\n  end if;\n  return jsonb_build_object(\n    'estado', case when e.status = 'pagado' then 'pagado' when e.status = 'anulado' then 'anulado'\n                   when c.pendiente < 0.005 then 'cobrada' when s.company_id is null or s.tarjeta <> 'activo' then 'sin_cobro' else 'abierto' end,\n    'empresa', coalesce(nullif(trim(co.trade_name), ''), co.legal_name), 'color', co.color,\n    'factura', v.number_text, 'fecha', v.issue_date, 'vence', v.due_date, 'total', c.total, 'pendiente', c.pendiente,\n    'metodos', case when s.company_id is null then '[]'::jsonb\n                    else jsonb_build_array('tarjeta') || case when s.bizum = 'activo' then '["bizum"]'::jsonb else '[]'::jsonb end end,\n    'pagado', case when e.status = 'pagado' then jsonb_build_object('el', e.pagado_at, 'con', e.metodo, 'importe', e.importe) end);\nend $function$\n	4ba701b29554c403930210e6e154ad0b	2026-10-28 05:27:04.450136+00
public.conta_iva_presentado(uuid,date)	20261027T1408_v04_iva_reabrir	CREATE OR REPLACE FUNCTION public.conta_iva_presentado(p_company uuid, p_fecha date)\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select jsonb_build_object('id', r.id, 'ejercicio', r.fiscal_year, 'periodo', r.period, 'cadencia', r.cadence,\n                            'desde', f.desde, 'hasta', f.hasta,\n                            'presentado', coalesce(r.filed_at, r.updated_at), 'secuencia', r.sequence)\n    from public.tax_return r\n   cross join lateral public.conta_impuesto_periodo_fechas(r.fiscal_year, r.period) f\n   where p_fecha is not null and r.company_id = p_company and r.form_code = '303'\n     and r.fiscal_year = extract(year from p_fecha)::int\n     and r.period ~ '^([1-4]T|0[1-9]|1[0-2])$'\n     and r.status in ('filed', 'booked', 'paid', 'offset', 'refunded')\n     and p_fecha between f.desde and f.hasta\n   order by r.sequence, r.filed_at nulls last\n   limit 1\n$function$\n	5129d8c98a3d27705b1788b2793a56aa	2026-10-27 14:55:29.304873+00
public.conta_iva_presentados(uuid,int)	20261027T1408_v04_iva_reabrir	CREATE OR REPLACE FUNCTION public.conta_iva_presentados(p_company uuid, p_year integer)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_cuenta uuid;\nbegin\n  select account_id into v_cuenta from public.company where id = p_company;\n  -- Quien es de la cuenta, o quien ve sus impuestos (su asesoría, con su consentimiento).\n  if v_cuenta is null or not (v_cuenta = any ((select public.current_user_account_ids())::uuid[]) or public.conta_impuesto_puede_ver(p_company)) then\n    raise exception 'No puedes ver esta empresa.' using errcode = '42501';\n  end if;\n  return coalesce((\n    select jsonb_agg(jsonb_build_object('periodo', r.period, 'ejercicio', r.fiscal_year, 'desde', f.desde, 'hasta', f.hasta,\n                                        'presentado', coalesce(r.filed_at, r.updated_at), 'declaracion', r.id,\n                                        'nombre', public.conta_iva_periodo_nombre(r.period, r.fiscal_year),\n                                        'siguiente', public.conta_iva_periodo_nombre(\n                                            public.conta_iva_periodo_de(r.cadence, coalesce(public.conta_primer_dia_iva_abierto(p_company, f.hasta + 1), f.hasta + 1)),\n                                            extract(year from coalesce(public.conta_primer_dia_iva_abierto(p_company, f.hasta + 1), f.hasta + 1))::int,\n                                            extract(year from coalesce(public.conta_primer_dia_iva_abierto(p_company, f.hasta + 1), f.hasta + 1))::int <> r.fiscal_year))\n                     order by f.desde)\n      from public.tax_return r\n     cross join lateral public.conta_impuesto_periodo_fechas(r.fiscal_year, r.period) f\n     where r.company_id = p_company and r.form_code = '303' and r.fiscal_year = p_year and r.sequence = 1\n       and r.period ~ '^([1-4]T|0[1-9]|1[0-2])$'\n       and r.status in ('filed', 'booked', 'paid', 'offset', 'refunded')), '[]'::jsonb);\nend $function$\n	1a16cde23b1c19c1c36161204c655a83	2026-10-27 14:55:29.304873+00
public.edit_clock_entry(uuid,timestamp with time zone,text,text,text)	20261028T0706_l1a_corregir_con_conformidad	CREATE OR REPLACE FUNCTION public.edit_clock_entry(p_entry_id uuid, p_datetime timestamp with time zone, p_reason text, p_type text DEFAULT NULL::text, p_actor_label text DEFAULT NULL::text)\n RETURNS clock_entries\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_acct uuid; v_emp uuid; v_row public.clock_entries;\nbegin\n  if coalesce(trim(p_reason),'') = '' then raise exception 'MOTIVO_OBLIGATORIO'; end if;\n  select employee_id into v_emp from public.clock_entries where id = p_entry_id;\n  if v_emp is null then raise exception 'FICHAJE_NO_EXISTE'; end if;\n  v_acct := public._account_of_employee(v_emp);\n  if not public.current_user_is_admin_of(v_acct) then raise exception 'NO_AUTORIZADO'; end if;\n  if p_type is not null and p_type not in ('entrada','salida') then raise exception 'TIPO_INVALIDO'; end if;\n\n  perform set_config('app.clock_edit_reason', p_reason, true);\n  perform set_config('app.clock_edit_actor', coalesce(p_actor_label,''), true);\n\n  update public.clock_entries\n     set datetime = p_datetime,\n         real_datetime = p_datetime,\n         type = coalesce(p_type, type)\n   where id = p_entry_id\n   returning * into v_row;\n  return v_row;\nend $function$\n	b2fd9f273ce2841ed6bb91ffcabdc5a8	2026-10-28 09:27:45.141282+00
public.employee_clock_status(uuid)	20261027T1215_l00_datos_de_los_trabajadores	CREATE OR REPLACE FUNCTION public.employee_clock_status(p_employee_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_acct      uuid;\n  v_last      clock_entries;\n  v_estado    text;\n  v_since     timestamptz;\n  v_hoy_ini   timestamptz;\n  v_min_hoy   numeric := 0;\n  v_abierta   timestamptz;\n  r           record;\n  v_ini       timestamptz := null;\nbegin\n  v_acct := public._account_of_employee(p_employee_id);\n  if v_acct is null then\n    raise exception 'employee_clock_status: empleado % no encontrado', p_employee_id;\n  end if;\n  if not (v_acct = any(public.current_user_account_ids())) then\n    raise exception 'employee_clock_status: sin acceso a la cuenta %', v_acct;\n  end if;\n\n  select * into v_last\n  from clock_entries ce\n  where ce.employee_id = p_employee_id and coalesce(ce.voided,false) = false\n  order by ce.real_datetime desc, ce.datetime desc\n  limit 1;\n\n  -- Dia natural de Madrid, no UTC. El fichaje de las 00:15 de Madrid es de\n  -- ayer en UTC, y contarlo como de hoy falsea el dia.\n  v_hoy_ini := (date_trunc('day', now() at time zone 'Europe/Madrid')) at time zone 'Europe/Madrid';\n\n  -- Minutos de HOY: pares cerrados + el tramo abierto hasta ahora. Se calcula\n  -- con real_datetime, igual que team_worked_shifts, para no dar dos cifras\n  -- distintas de las mismas horas.\n  for r in\n    select ce.type, coalesce(ce.real_datetime, ce.datetime) as rt\n    from clock_entries ce\n    where ce.employee_id = p_employee_id\n      and coalesce(ce.voided,false) = false\n      and coalesce(ce.real_datetime, ce.datetime) >= v_hoy_ini\n    order by 2 asc\n  loop\n    if r.type = 'entrada' then\n      v_ini := r.rt;\n    elsif r.type = 'salida' and v_ini is not null then\n      v_min_hoy := v_min_hoy + extract(epoch from (r.rt - v_ini)) / 60.0;\n      v_ini := null;\n    end if;\n  end loop;\n\n  if v_last.id is null then\n    v_estado := 'sin_fichajes';\n  elsif v_last.type in ('entrada','pausa_inicio','pausa_fin') then\n    v_estado := 'trabajando';\n    -- Desde cuando: la ULTIMA entrada no anulada (una pausa no reabre jornada).\n    -- Se devuelve `datetime`, la hora OFICIAL: es la que ve el trabajador y la\n    -- que cita el parte. Enseñar la real descuadraria la ficha con el reloj de\n    -- todos los demas en los 68 fichajes que llevan redondeo.\n    select ce.datetime into v_since\n    from clock_entries ce\n    where ce.employee_id = p_employee_id and coalesce(ce.voided,false) = false\n      and ce.type = 'entrada'\n    order by coalesce(ce.real_datetime, ce.datetime) desc\n    limit 1;\n    v_abierta := v_since;\n    if v_ini is not null then\n      v_min_hoy := v_min_hoy + extract(epoch from (now() - v_ini)) / 60.0;\n    end if;\n  else\n    v_estado := 'fuera';\n    v_since  := v_last.datetime;\n  end if;\n\n  -- "Sin fichajes hoy" tambien cuando el ultimo evento es de otro dia y fue\n  -- una salida: la ficha no debe decir "Fuera" sin mas si hoy no ha pasado nada.\n  if v_estado = 'fuera'\n     and coalesce(v_last.real_datetime, v_last.datetime) < v_hoy_ini then\n    v_estado := 'sin_fichajes';\n  end if;\n\n  return jsonb_build_object(\n    'employee_id',    p_employee_id,\n    'estado',         v_estado,\n    'since',          v_since,\n    'abierta_desde',  v_abierta,\n    'minutos_hoy',    round(v_min_hoy, 1),\n    'ultimo_tipo',    v_last.type,\n    'ultimo_at',      v_last.datetime\n  );\nend;\n$function$\n	dc9da874fe60eff955c5b2acbd3982d9	2026-10-27 21:45:38.707296+00
public.employee_clock_status(uuid)	20261027T1905_l1a_fichar_en_el_servidor	CREATE OR REPLACE FUNCTION public.employee_clock_status(p_employee_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_acct      uuid;\n  v_last      clock_entries;\n  v_estado    text;\n  v_since     timestamptz;\n  v_hoy_ini   timestamptz;\n  v_min_hoy   numeric := 0;\n  v_abierta   timestamptz;\n  r           record;\n  v_ini       timestamptz := null;\nbegin\n  v_acct := public._account_of_employee(p_employee_id);\n  if v_acct is null then\n    raise exception 'employee_clock_status: empleado % no encontrado', p_employee_id;\n  end if;\n  -- L00 (27/10/2026): antes bastaba con ser de la cuenta. Ahora, tú mismo, o el\n  -- administrador o el encargado de la cuenta.\n  if not (public.current_user_is_admin_or_manager_of(v_acct) or public.current_user_is_employee(p_employee_id, v_acct)) then\n    raise exception 'employee_clock_status: sin acceso a la cuenta %', v_acct;\n  end if;\n\n  select * into v_last\n  from clock_entries ce\n  where ce.employee_id = p_employee_id and coalesce(ce.voided,false) = false\n  order by ce.real_datetime desc, ce.datetime desc\n  limit 1;\n\n  -- Dia natural de Madrid, no UTC. El fichaje de las 00:15 de Madrid es de\n  -- ayer en UTC, y contarlo como de hoy falsea el dia.\n  v_hoy_ini := (date_trunc('day', now() at time zone 'Europe/Madrid')) at time zone 'Europe/Madrid';\n\n  -- Minutos de HOY: pares cerrados + el tramo abierto hasta ahora. Se calcula\n  -- con real_datetime, igual que team_worked_shifts, para no dar dos cifras\n  -- distintas de las mismas horas.\n  for r in\n    select ce.type, coalesce(ce.real_datetime, ce.datetime) as rt\n    from clock_entries ce\n    where ce.employee_id = p_employee_id\n      and coalesce(ce.voided,false) = false\n      and coalesce(ce.real_datetime, ce.datetime) >= v_hoy_ini\n    order by 2 asc\n  loop\n    if r.type = 'entrada' then\n      v_ini := r.rt;\n    elsif r.type = 'salida' and v_ini is not null then\n      v_min_hoy := v_min_hoy + extract(epoch from (r.rt - v_ini)) / 60.0;\n      v_ini := null;\n    end if;\n  end loop;\n\n  if v_last.id is null then\n    v_estado := 'sin_fichajes';\n  elsif v_last.type in ('entrada','pausa_inicio','pausa_fin') then\n    v_estado := 'trabajando';\n    -- Desde cuando: la ULTIMA entrada no anulada (una pausa no reabre jornada).\n    -- Se devuelve `datetime`, la hora OFICIAL: es la que ve el trabajador y la\n    -- que cita el parte. Enseñar la real descuadraria la ficha con el reloj de\n    -- todos los demas en los 68 fichajes que llevan redondeo.\n    select ce.datetime into v_since\n    from clock_entries ce\n    where ce.employee_id = p_employee_id and coalesce(ce.voided,false) = false\n      and ce.type = 'entrada'\n    order by coalesce(ce.real_datetime, ce.datetime) desc\n    limit 1;\n    v_abierta := v_since;\n    if v_ini is not null then\n      v_min_hoy := v_min_hoy + extract(epoch from (now() - v_ini)) / 60.0;\n    end if;\n  else\n    v_estado := 'fuera';\n    v_since  := v_last.datetime;\n  end if;\n\n  -- "Sin fichajes hoy" tambien cuando el ultimo evento es de otro dia y fue\n  -- una salida: la ficha no debe decir "Fuera" sin mas si hoy no ha pasado nada.\n  if v_estado = 'fuera'\n     and coalesce(v_last.real_datetime, v_last.datetime) < v_hoy_ini then\n    v_estado := 'sin_fichajes';\n  end if;\n\n  return jsonb_build_object(\n    'employee_id',    p_employee_id,\n    'estado',         v_estado,\n    'since',          v_since,\n    'abierta_desde',  v_abierta,\n    'minutos_hoy',    round(v_min_hoy, 1),\n    'ultimo_tipo',    v_last.type,\n    'ultimo_at',      v_last.datetime\n  );\nend;\n$function$\n	c33d135d4e00a41ff23348c1cb291a6e	2026-10-28 05:46:23.932303+00
public.export_gestoria_mensual(uuid,date,date)	20261029T0730_l1a_cerrar_escritura_directa	CREATE OR REPLACE FUNCTION public.export_gestoria_mensual(p_account uuid, p_from date, p_to date)\n RETURNS TABLE(empleado text, dni text, local text, dias_trabajados integer, horas_trabajadas numeric, horas_nocturnas numeric, dias_vacaciones integer, dias_baja integer, dias_festivo_trabajado integer, horas_contratadas numeric, delta_horas numeric, incidencias text)\n LANGUAGE sql\n STABLE\nAS $function$\n  select e.name, e.dni, l.name,\n    t.dias_trabajados, t.horas_trabajadas, t.horas_nocturnas,\n    t.dias_vacaciones, t.dias_baja, t.dias_festivo_trabajado,\n    t.horas_contratadas, t.delta_horas,\n    nullif(concat_ws(' · ',\n      case when e.dni is null or e.dni = '' then 'SIN DNI' end,\n      case when t.horas_pausa = 0 and t.horas_trabajadas > 0 then 'sin descansos registrados' end,\n      case when abs(t.delta_horas) > 20 then 'desvío de '||round(t.delta_horas,1)||' h sobre contrato' end,\n      case when exists (\n        select 1 from public.registro_jornada_mensual(e.id, p_from, p_to) r\n        where r.salida is not null\n          and extract(hour from (r.salida at time zone 'Europe/Madrid')) between 4 and 10\n      ) then 'posible fichaje de salida olvidado' end\n    ), '')\n  from public.employees e\n  join public.locations l on l.id = e.location_id\n  cross join lateral public.registro_jornada_totales(e.id, p_from, p_to) t\n  where e.account_id = p_account and e.active\n  order by e.name;\n$function$\n	152170eaa421882bdd0e2869ab1f8aa2	2026-10-29 08:33:24.590125+00
public.f01_pasada_last(uuid)	20261028T0851_f01c_cola_y_pasada	CREATE OR REPLACE FUNCTION public.f01_pasada_last(p_account uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_a       record;\n  v_vinc    jsonb;\n  v_ventas  jsonb;\n  v_salida  jsonb := '[]'::jsonb;\nbegin\n  for v_a in select a.* from public.external_brand_alta a\n               join public.brand b on b.id = a.brand_id and b.archived_at is null\n              where a.account_id = p_account and a.source = 'lastapp'\n  loop\n    v_vinc := public._f01_vincular(p_account, v_a.brand_id, v_a.external_org_id, v_a.external_brand_name, false, 'F01 · pasada de Last');\n    if (v_vinc->>'vinculos_nuevos')::integer > 0 then\n      v_ventas := public._f01_recolocar(p_account, v_a.brand_id, v_a.external_org_id, v_a.external_brand_name);\n      v_salida := v_salida || jsonb_build_object('marca', v_a.external_brand_name, 'vinculos_nuevos', v_vinc->'vinculos_nuevos', 'ventas', v_ventas);\n    end if;\n  end loop;\n  return jsonb_build_object('marcas_con_vinculos_nuevos', v_salida);\nend $function$\n	d73f9c9411423e6e88bfe6597dc49fa0	2026-10-28 11:55:00.025925+00
public.fiscal_for_preview(uuid)	20261027T0741_v04_tique_verifactu	CREATE OR REPLACE FUNCTION public.fiscal_for_preview(p_sale_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_acc uuid; v_q jsonb; v_t public.ticket_invoice; v_code text; v_loc uuid; v_raw jsonb;\nbegin\n  select account_id, location_id, public.safe_jsonb(raw_tab) into v_acc, v_loc, v_raw from public.sale where id = p_sale_id;\n  if v_acc is null or not public.belongs_to_account(v_acc) then raise exception 'Ese pedido no está.' using errcode = 'P0002'; end if;\n  v_q := public._ticket_quien_factura(v_acc, p_sale_id);\n  if v_q->>'tipo' = 'cedida' then\n    return jsonb_build_object('legalName', v_q->>'legalName', 'taxId', v_q->>'taxId', 'address', v_q->>'address',\n      'ticketNumber', v_q->>'number', 'issuerKind', 'cedida', 'sinFactura', (v_q->>'sinFactura')::boolean, 'serie', false, 'pendiente', false);\n  end if;\n  select * into v_t from public.ticket_invoice where account_id = v_acc and sale_id = p_sale_id and kind = 'F';\n  select code into v_code from public.location_invoice_code where location_id = v_loc and account_id = v_acc;\n  return jsonb_build_object('legalName', v_q->>'legalName', 'taxId', v_q->>'taxId', 'address', null,\n    'ticketNumber', coalesce(v_t.number_text, case when v_code is null then coalesce(v_raw->'bills'->0->>'number', v_raw->>'number') end),\n    'issuerKind', 'propia', 'sinFactura', false, 'serie', v_t.id is not null,\n    -- El local numera, pero este pedido aún no se ha impreso: el número llega al imprimir.\n    'pendiente', v_t.id is null and v_code is not null);\nend $function$\n	98888cc6c78521de565f0cf0cd6b3626	2026-10-27 09:45:29.27972+00
public.fiscal_for_print(text,uuid)	20261026T2309_v04_tique_serie_y_quien_factura	CREATE OR REPLACE FUNCTION public.fiscal_for_print(p_device_token text, p_sale_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\ndeclare\r\n  v_device  kds_device;\r\n  v_acc     uuid;\r\n  v_a       accounts%ROWTYPE;\r\n  v_raw     jsonb;\r\n  v_num     text;\r\n  v_addr    text;\r\nbegin\r\n  v_device := public.kds_resolve_device(p_device_token);\r\n  if v_device.id is null then raise exception 'fiscal_for_print: token no válido'; end if;\r\n  v_acc := v_device.account_id;\r\n\r\n  select * into v_a from accounts where id = v_acc;\r\n\r\n  select safe_jsonb(raw_tab) into v_raw from sale where id = p_sale_id and account_id = v_acc;\r\n  v_num := coalesce(v_raw->'bills'->0->>'number', v_raw->>'number');\r\n\r\n  -- Dirección desde billing_address jsonb {street, postalCode, city, province}\r\n  v_addr := nullif(btrim(concat_ws(', ',\r\n              nullif(v_a.billing_address->>'street',''),\r\n              nullif(concat_ws(' ', v_a.billing_address->>'postalCode', v_a.billing_address->>'city'), ''),\r\n              nullif(v_a.billing_address->>'province',''))), '');\r\n\r\n  return jsonb_build_object(\r\n    'legalName', coalesce(v_a.legal_name, v_a.name),\r\n    'taxId', v_a.cif,\r\n    'address', v_addr,\r\n    'ticketNumber', v_num\r\n  );\r\nend;\r\n$function$\n	6efe86f51f4bc6a1f336a68bf0875c49	2026-10-27 06:15:49.328813+00
public.fiscal_for_print(text,uuid)	20261027T0741_v04_tique_verifactu	CREATE OR REPLACE FUNCTION public.fiscal_for_print(p_device_token text, p_sale_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_device kds_device; v_acc uuid; v_q jsonb; v_loc uuid; v_brand uuid; v_raw jsonb; v_code text; v_t public.ticket_invoice; v_num text;\nbegin\n  -- Igual que antes: sin un token bueno no hay tique (y la tablet lo sabe).\n  v_device := public.kds_resolve_device(p_device_token);\n  if v_device.id is null then raise exception 'fiscal_for_print: token no válido'; end if;\n  v_acc := v_device.account_id;\n\n  begin\n    select location_id, brand_id, public.safe_jsonb(raw_tab) into v_loc, v_brand, v_raw from public.sale where id = p_sale_id and account_id = v_acc;\n    v_q := public._ticket_quien_factura(v_acc, p_sale_id);\n  exception when others then\n    v_q := null;\n    perform public._ticket_aviso('tique_sin_quien_factura', 'Un tique ha salido sin saber quién factura',\n      'No se ha podido leer quién factura el pedido al imprimir su tique (' || sqlerrm || '). Ha salido como antes. Míralo en Ajustes › Facturas de los pedidos.',\n      'tique_sin_quien_factura:' || v_acc::text, interval '1 hour', v_acc, v_loc, v_brand, 'alto');\n  end;\n  if v_q is null then\n    begin return public._ticket_fiscal_de_antes(v_acc, p_sale_id);\n    exception when others then return jsonb_build_object('legalName', null, 'taxId', null, 'address', null, 'ticketNumber', null);\n    end;\n  end if;\n\n  if v_q->>'tipo' = 'cedida' then\n    if (v_q->>'sinFactura')::boolean then\n      -- Nunca se inventa un número: el tique va sin la línea, y se avisa.\n      perform public._ticket_aviso('tique_cedida_sin_factura',\n        'Un pedido de una marca cedida llegó sin la factura de Last',\n        'El tique de la bolsa ha salido sin «Factura Simplificada»: el pedido de una marca cedida no trae la factura del socio (raw_tab.bills). Míralo en Last.',\n        'tique_cedida_sin_factura:' || p_sale_id::text, interval '7 days', v_acc, v_loc, v_brand, 'aviso');\n    end if;\n    return jsonb_build_object('legalName', v_q->>'legalName', 'taxId', v_q->>'taxId', 'address', v_q->>'address',\n      'ticketNumber', v_q->>'number', 'issuerKind', 'cedida', 'sinFactura', (v_q->>'sinFactura')::boolean, 'serie', false);\n  end if;\n\n  -- Propia: el número de la serie del local, si el local tiene código.\n  begin\n    select code into v_code from public.location_invoice_code where location_id = v_loc and account_id = v_acc;\n    if v_code is not null then\n      v_t := public._ticket_invoice_number(v_acc, v_loc, p_sale_id, v_code, v_q->>'legalName', v_q->>'taxId');\n      v_num := v_t.number_text;\n    end if;\n  exception when others then\n    -- La impresión no se cae por esto: el tique sale como antes y se avisa.\n    v_num := null; v_t := null;\n    perform public._ticket_aviso('tique_sin_numero',\n      'Un tique ha salido sin el número de su serie',\n      'No se ha podido dar el número de la serie del local al imprimir el tique (' || sqlerrm || '). El tique ha salido con el número del pedido. Míralo en Ajustes › Facturas de los pedidos.',\n      'tique_sin_numero:' || coalesce(v_loc::text, v_acc::text), interval '1 hour', v_acc, v_loc, v_brand, 'alto');\n  end;\n  if v_num is null then\n    -- Como antes: el número de la plataforma o del TPV, si lo trae (si no, la tablet pone el del pedido).\n    v_num := coalesce(v_raw->'bills'->0->>'number', v_raw->>'number');\n  end if;\n  return jsonb_build_object('legalName', v_q->>'legalName', 'taxId', v_q->>'taxId', 'address', null,\n    'ticketNumber', v_num, 'issuerKind', 'propia', 'sinFactura', false, 'serie', v_t.id is not null);\nend;\n$function$\n	f32a7c7463489e196da962f3536fb64d	2026-10-27 09:45:29.27972+00
public.journal_entry_validar(uuid,text)	20261028T0735_s01_enlace_validado	CREATE OR REPLACE FUNCTION public.journal_entry_validar(p_entry uuid, p_quien_nombre text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_e public.journal_entry;\n  v_numero int; v_seq bigint; v_prev text; v_hash text; v_mal text;\nbegin\n  select * into v_e from public.journal_entry where id = p_entry for update;\n  if v_e.id is null then raise exception 'Ese asiento no existe.' using errcode = 'P0002'; end if;\n  if not public.current_user_is_admin_or_manager_of(v_e.account_id) then\n    raise exception 'Solo un administrador o un encargado de la cuenta valida asientos.' using errcode = '42501';\n  end if;\n  if v_e.status not in ('propuesto', 'borrador') then\n    raise exception 'El asiento ya está %.', v_e.status using errcode = '23514';\n  end if;\n\n  -- Reglas 1, 4 y 5 y el envío por aclarar: el primer motivo, con su texto.\n  -- La regla vive en conta_motivos_para_validar (M01, 16/10).\n  select m.motivo into v_mal from public.conta_motivos_para_validar(p_entry) m order by m.orden limit 1;\n  if v_mal is not null then raise exception '%', v_mal using errcode = '23514'; end if;\n\n  -- Regla 2: número siguiente de su serie en el ejercicio, sin huecos. Huella encadenada.\n  perform pg_advisory_xact_lock(hashtextextended('journal_entry_numero:' || v_e.company_id, 0));\n  select coalesce(max(number), 0) + 1 into v_numero from public.journal_entry\n   where company_id = v_e.company_id and fiscal_year_id = v_e.fiscal_year_id and series = v_e.series and number is not null;\n  select chain_seq, hash into v_seq, v_prev from public.journal_entry\n   where company_id = v_e.company_id and chain_seq is not null order by chain_seq desc limit 1;\n  v_seq := coalesce(v_seq, 0) + 1;\n\n  update public.journal_entry set number = v_numero, status = 'validado', validated_at = now(), validated_by = auth.uid(),\n         validated_by_name = coalesce(p_quien_nombre, public.conta_nombre_actor()), chain_seq = v_seq, prev_hash = v_prev,\n         hash = 'pendiente'\n   where id = p_entry;\n  v_hash := public.journal_huella(v_prev, public.journal_entry_canonico(p_entry));\n  -- La huella se escribe en la misma transacción: el disparador deja pasar este\n  -- cambio porque el asiento acaba de validarse (journal_entry_inalterable, 0100).\n  perform set_config('folvy.journal_huella', p_entry::text, true);\n  update public.journal_entry set hash = v_hash where id = p_entry;\n  perform set_config('folvy.journal_huella', '', true);\n  return jsonb_build_object('id', p_entry, 'serie', v_e.series, 'numero', v_numero, 'huella', v_hash);\nend $function$\n	af2a49f039b46fec80c7dea2dceb6022	2026-10-28 11:33:52.724436+00
public.kitchen_ancestors_of(uuid)	20261027T1647_l00_ancestros_por_cuenta	CREATE OR REPLACE FUNCTION public.kitchen_ancestors_of(p_item_id uuid)\n RETURNS TABLE(ancestor_id uuid, depth integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_account_id uuid;\r\nBEGIN\r\n  SELECT account_id INTO v_account_id FROM recipe_item WHERE id = p_item_id;\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'kitchen_ancestors_of: item % no existe', p_item_id;\r\n  END IF;\r\n\r\n  -- Guard de tenancy idéntico al resto de funciones kitchen.\r\n  IF NOT (public.current_user_is_admin()\r\n          OR public.current_user_is_admin_or_manager_of(v_account_id)) THEN\r\n    RAISE EXCEPTION 'kitchen_ancestors_of: sin acceso al item %', p_item_id;\r\n  END IF;\r\n\r\n  RETURN QUERY\r\n  WITH RECURSIVE ancestros AS (\r\n    -- Nivel 1: quién usa p_item_id directamente.\r\n    SELECT rl.parent_item_id AS ancestor_id, 1 AS depth\r\n    FROM recipe_line rl\r\n    WHERE rl.child_item_id = p_item_id\r\n    UNION\r\n    -- Niveles superiores: quién usa a esos ancestros.\r\n    SELECT rl.parent_item_id, a.depth + 1\r\n    FROM recipe_line rl\r\n    JOIN ancestros a ON rl.child_item_id = a.ancestor_id\r\n  )\r\n  -- Si un ítem aparece a varias profundidades (lo usa por dos caminos),\r\n  -- nos quedamos con la MÁS profunda → garantiza recalcularlo después de\r\n  -- todos sus hijos. La app ordenará por depth DESC.\r\n  SELECT anc.ancestor_id, MAX(anc.depth) AS depth\r\n  FROM ancestros anc\r\n  GROUP BY anc.ancestor_id\r\n  ORDER BY MAX(anc.depth) DESC;\r\nEND;\r\n$function$\n	eb870caad89351772bd8e003c94082d7	2026-10-27 21:45:47.907223+00
public.request_clock_correction(uuid,uuid,text,text,uuid,text,timestamp with time zone)	20261028T0706_l1a_corregir_con_conformidad	CREATE OR REPLACE FUNCTION public.request_clock_correction(p_employee_id uuid, p_requested_by_employee_id uuid, p_kind text, p_reason text, p_clock_entry_id uuid DEFAULT NULL::uuid, p_proposed_type text DEFAULT NULL::text, p_proposed_datetime timestamp with time zone DEFAULT NULL::timestamp with time zone)\n RETURNS clock_correction_request\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\ndeclare v_acct uuid; v_row public.clock_correction_request;\r\nbegin\r\n  if coalesce(trim(p_reason),'') = '' then raise exception 'MOTIVO_OBLIGATORIO'; end if;\r\n  if p_kind not in ('add','edit','void') then raise exception 'TIPO_INVALIDO'; end if;\r\n  v_acct := public._account_of_employee(p_employee_id);\r\n  if v_acct is null or not (v_acct = any (public.current_user_account_ids())) then raise exception 'NO_AUTORIZADO'; end if;\r\n\r\n  insert into public.clock_correction_request(\r\n    account_id, employee_id, requested_by_employee_id, clock_entry_id, kind, proposed_type, proposed_datetime, reason)\r\n  values (v_acct, p_employee_id, p_requested_by_employee_id, p_clock_entry_id, p_kind, p_proposed_type, p_proposed_datetime, p_reason)\r\n  returning * into v_row;\r\n\r\n  insert into public.clock_entry_audit(\r\n    clock_entry_id, employee_id, account_id, action, actor_employee_id, reason, after)\r\n  values (p_clock_entry_id, p_employee_id, v_acct, 'request', p_requested_by_employee_id, p_reason, to_jsonb(v_row));\r\n  return v_row;\r\nend $function$\n	612536bfd99d6e60c78c92deaf35db01	2026-10-28 09:27:45.141282+00
public.resolve_clock_correction(uuid,boolean,text,text)	20261028T0706_l1a_corregir_con_conformidad	CREATE OR REPLACE FUNCTION public.resolve_clock_correction(p_request_id uuid, p_approve boolean, p_note text DEFAULT NULL::text, p_actor_label text DEFAULT NULL::text)\n RETURNS clock_correction_request\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare r public.clock_correction_request; v_new public.clock_entries; v_loc uuid;\nbegin\n  select * into r from public.clock_correction_request where id = p_request_id for update;\n  if r.id is null then raise exception 'SOLICITUD_NO_EXISTE'; end if;\n  if not public.current_user_is_admin_of(r.account_id) then raise exception 'NO_AUTORIZADO'; end if;\n  if r.status <> 'pending' then raise exception 'YA_RESUELTA'; end if;\n\n  if p_approve then\n    perform set_config('app.clock_edit_reason', 'Solicitud del trabajador: '||r.reason, true);\n    perform set_config('app.clock_edit_actor', coalesce(p_actor_label,''), true);\n\n    if r.kind = 'add' then\n      select location_id into v_loc from public.employees where id = r.employee_id;\n      insert into public.clock_entries(employee_id, type, datetime, real_datetime, source, address, location_id_at_clock)\n      values (r.employee_id, r.proposed_type, r.proposed_datetime, r.proposed_datetime, 'manual', 'Aprobado · '||r.reason, v_loc)\n      returning * into v_new;\n      insert into public.clock_entry_audit(\n        clock_entry_id, employee_id, account_id, action, actor_user_id, actor_label, reason, after)\n      values (v_new.id, r.employee_id, r.account_id, 'create_manual', auth.uid(), p_actor_label, r.reason,\n              public._clock_snapshot(v_new));\n    elsif r.kind = 'edit' and r.clock_entry_id is not null then\n      update public.clock_entries set datetime = r.proposed_datetime, real_datetime = r.proposed_datetime, type = coalesce(r.proposed_type, type)\n       where id = r.clock_entry_id;\n    elsif r.kind = 'void' and r.clock_entry_id is not null then\n      update public.clock_entries set voided = true where id = r.clock_entry_id;\n    end if;\n  end if;\n\n  update public.clock_correction_request\n     set status = case when p_approve then 'approved' else 'rejected' end,\n         resolved_by_user_id = auth.uid(), resolved_at = now(), resolution_note = p_note\n   where id = p_request_id\n   returning * into r;\n\n  insert into public.clock_entry_audit(\n    clock_entry_id, employee_id, account_id, action, actor_user_id, actor_label, reason)\n  values (r.clock_entry_id, r.employee_id, r.account_id,\n          case when p_approve then 'approve' else 'reject' end, auth.uid(), p_actor_label,\n          coalesce(p_note, r.reason));\n\n  insert into public.employee_notifications(employee_id, type, title, body, data)\n  values (r.requested_by_employee_id, 'clock_correction_resolved',\n          case when p_approve then 'Corrección aprobada' else 'Corrección rechazada' end,\n          coalesce(p_note, r.reason),\n          jsonb_build_object('request_id', r.id, 'status', r.status));\n  return r;\nend $function$\n	953ac87ed1469478bdd26fbe7eba7f2a	2026-10-28 09:27:45.141282+00
public.seed_catalog_canonical(uuid,boolean,interval)	20261027T1322_f01_sembrado_y_socio	CREATE OR REPLACE FUNCTION public.seed_catalog_canonical(p_account_id uuid, p_dry_run boolean, p_margen_foto interval DEFAULT '1 day'::interval)\n RETURNS TABLE(dry_run boolean, matriculas_miradas integer, base_ya_existentes integer, productos_base_creados integer, overrides_creados integer, overrides_de_foto_vieja integer, productos_sin_revisar_precios integer, saltados_sin_marca integer, saltados_por_integracion_no_cedida integer, saltados_por_ser_propia integer, saltados_por_no_estar_en_la_foto integer, marcas_sin_resolver text[], marcas_de_integracion_no_cedida text[], marcas_propias_saltadas text[], no_en_la_foto jsonb, fotos jsonb)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_unit_ud    uuid := '869711c3-eabd-4e95-92f2-555efaaba6b0'; -- "Unidad" (global)\n  v_prod       record;\n  v_chan       record;\n  v_brand_id   uuid;\n  v_own        text;\n  v_recipe_id  uuid;\n  v_menu_id    uuid;\n  v_base_price numeric;\n  v_mir        integer := 0;\n  v_ya         integer := 0;\n  v_base       integer := 0;\n  v_over       integer := 0;\n  v_over_vieja integer := 0;\n  v_over_norg  integer := 0;\n  v_nomarca    integer := 0;\n  v_norg       integer := 0;\n  v_propia     integer := 0;\n  v_vieja      integer := 0;\n  v_marcas_nom text[] := '{}';\n  v_marcas_org text[] := '{}';\n  v_marcas_pro text[] := '{}';\n  v_lista      jsonb  := '[]'::jsonb;\n  v_fotos      jsonb;\nBEGIN\n  -- Guarda de tenancy (SECURITY DEFINER salta RLS).\n  IF NOT (public.current_user_is_admin()\n          OR public.current_user_is_admin_or_manager_of(p_account_id)) THEN\n    RAISE EXCEPTION 'seed_catalog_canonical: sin acceso a la cuenta %', p_account_id;\n  END IF;\n\n  -- La foto de cada org: cuándo se refrescó su espejo por última vez. Va en el\n  -- resultado porque sembrar de una foto vieja es una decisión, no un detalle.\n  SELECT coalesce(jsonb_agg(jsonb_build_object(\n           'org',          t.external_org_id,\n           'nombre',       t.nombre,\n           'tipo',         t.tipo,\n           'ultima_foto',  t.ultima_foto,\n           'horas',        round(extract(epoch FROM (now() - t.ultima_foto)) / 3600.0, 1),\n           'filas',        t.filas)\n           ORDER BY t.ultima_foto DESC), '[]'::jsonb)\n    INTO v_fotos\n    FROM (SELECT ecp.external_org_id,\n                 max(ei.organization_name)   AS nombre,\n                 max(ei.ownership_type)      AS tipo,\n                 max(ecp.seen_in_catalog_at) AS ultima_foto,\n                 count(*)                    AS filas\n            FROM public.external_catalog_product ecp\n            LEFT JOIN public.external_integration ei\n                   ON ei.account_id = ecp.account_id\n                  AND ei.source = 'lastapp'\n                  AND ei.external_org_id = ecp.external_org_id\n           WHERE ecp.account_id = p_account_id\n           GROUP BY ecp.external_org_id) t;\n\n  FOR v_prod IN\n    WITH foto AS (\n      SELECT ecp.external_org_id, max(ecp.seen_in_catalog_at) AS ultima_foto\n        FROM public.external_catalog_product ecp\n       WHERE ecp.account_id = p_account_id\n       GROUP BY ecp.external_org_id\n    )\n    SELECT\n      ecp.organization_product_id::text AS matricula,\n      max(ecp.external_brand_name)      AS brand_name,\n      coalesce(\n        max(ecp.product_name) FILTER (WHERE ecp.external_channel = 'default'),\n        max(ecp.product_name)\n      ) AS product_name,\n      coalesce(\n        max(ecp.price_cents) FILTER (WHERE ecp.external_channel = 'default'),\n        (SELECT mode() WITHIN GROUP (ORDER BY ecp2.price_cents)\n           FROM external_catalog_product ecp2\n          WHERE ecp2.account_id = p_account_id\n            AND ecp2.organization_product_id = ecp.organization_product_id\n            AND ecp2.price_cents IS NOT NULL)\n      ) AS base_cents,\n      max(ecp.seen_in_catalog_at) AS visto,\n      -- ¿Viene de una integración CEDIDA y viva? Se pregunta por el ORIGEN del\n      -- dato, no por la etiqueta de la marca: es donde vive el hecho.\n      bool_or(ei.ownership_type = 'licensed' AND ei.is_active) AS de_cedida,\n      -- ¿Y estaba en la última foto de ESA org cedida? (no «de los últimos N días»,\n      -- y no la foto de una org muerta, que siempre parece fresca)\n      bool_or(ei.ownership_type = 'licensed' AND ei.is_active\n              AND ecp.seen_in_catalog_at >= f.ultima_foto - p_margen_foto) AS en_foto_de_cedida\n    FROM external_catalog_product ecp\n    JOIN foto f ON f.external_org_id = ecp.external_org_id\n    LEFT JOIN external_integration ei\n           ON ei.account_id = ecp.account_id\n          AND ei.source = 'lastapp'\n          AND ei.external_org_id = ecp.external_org_id\n    WHERE ecp.account_id = p_account_id\n      AND ecp.organization_product_id IS NOT NULL\n      AND ecp.external_brand_name IS NOT NULL\n      AND ecp.external_brand_name <> 'FOODINT'\n    GROUP BY ecp.organization_product_id\n  LOOP\n    v_mir := v_mir + 1;\n\n    -- ── 1. ¿Resuelve la marca? (alias Dirty Burgers→Dirty Burger) ──────────\n    SELECT b.id, b.ownership_type INTO v_brand_id, v_own\n    FROM brand b\n    WHERE b.account_id = p_account_id\n      AND b.is_active IS NOT FALSE\n      AND lower(btrim(b.name)) = lower(btrim(\n            CASE WHEN v_prod.brand_name = 'Dirty Burgers' THEN 'Dirty Burger'\n                 ELSE v_prod.brand_name END))\n    LIMIT 1;\n\n    IF v_brand_id IS NULL THEN\n      v_nomarca := v_nomarca + 1;\n      IF NOT (v_prod.brand_name = ANY (v_marcas_nom)) THEN\n        v_marcas_nom := v_marcas_nom || v_prod.brand_name;\n      END IF;\n      CONTINUE;\n    END IF;\n\n    v_base_price := COALESCE(v_prod.base_cents, 0)::numeric / 100.0;\n\n    -- ── 2. ¿Ya existe la capa base? ───────────────────────────────────────\n    SELECT mi.id INTO v_menu_id\n    FROM menu_item mi\n    WHERE mi.account_id = p_account_id\n      AND mi.external_source = 'lastapp'\n      AND mi.external_id = v_prod.matricula\n      AND mi.brand_id = v_brand_id\n      AND mi.channel_id IS NULL\n      AND mi.archived_at IS NULL\n    LIMIT 1;\n\n    IF v_menu_id IS NOT NULL THEN\n      v_ya := v_ya + 1;\n    ELSE\n      -- ── 3. Guarda de ORIGEN: sólo se siembra de una integración CEDIDA y viva ──\n      -- Va DELANTE de la de marca porque pregunta por el sitio donde el hecho\n      -- vive de verdad. La etiqueta de la marca puede estar mal —y lo está:\n      -- «Lobbers» figura como `licensed` y sus 22 matrículas sólo existen en la\n      -- org de las PROPIAS, que además está muerta. Preguntando por la marca se\n      -- colaban sus 9 platos; preguntando por la integración, no.\n      IF NOT COALESCE(v_prod.de_cedida, false) THEN\n        v_norg := v_norg + 1;\n        IF NOT (v_prod.brand_name = ANY (v_marcas_org)) THEN\n          v_marcas_org := v_marcas_org || v_prod.brand_name;\n        END IF;\n        CONTINUE;\n      END IF;\n\n      -- ── 4. Guarda de propiedad: sembrar es cosa de marcas CEDIDAS ───────\n      -- Lo de una marca propia es de Folvy: su escandallo se hace aquí, no se\n      -- copia de lo que el TPV enseña al cliente. Se cuenta y se LISTA, no se\n      -- salta en silencio (regla 7).\n      IF v_own IS DISTINCT FROM 'licensed' THEN\n        v_propia := v_propia + 1;\n        IF NOT (v_prod.brand_name = ANY (v_marcas_pro)) THEN\n          v_marcas_pro := v_marcas_pro || v_prod.brand_name;\n        END IF;\n        CONTINUE;\n      END IF;\n\n      -- ── 5. Guarda de foto: sólo lo que estaba la última vez que miramos ──\n      -- Sembrar de una foto vieja no es sembrar, es resucitar. Sale con su\n      -- fecha, para que se pueda mirar antes de decidir.\n      IF NOT COALESCE(v_prod.en_foto_de_cedida, false) THEN\n        v_vieja := v_vieja + 1;\n        v_lista := v_lista || jsonb_build_object(\n          'producto',             v_prod.product_name,\n          'marca',                v_prod.brand_name,\n          'visto_por_ultima_vez', v_prod.visto);\n        CONTINUE;\n      END IF;\n\n      -- ── 6. Crear: artículo físico + presentación base ───────────────────\n      IF NOT p_dry_run THEN\n        INSERT INTO recipe_item (account_id, type, name, base_unit_id, is_active, source, needs_review)\n        VALUES (p_account_id, 'dish', v_prod.product_name, v_unit_ud, true, 'import', true)\n        RETURNING id INTO v_recipe_id;\n\n        INSERT INTO menu_item (account_id, brand_id, channel_id, recipe_item_id, name, price,\n                               product_type, external_source, external_id, source, needs_review)\n        VALUES (p_account_id, v_brand_id, NULL, v_recipe_id, v_prod.product_name, v_base_price,\n                'item', 'lastapp', v_prod.matricula, 'import', true)\n        RETURNING id INTO v_menu_id;\n      END IF;\n      v_base := v_base + 1;\n    END IF;\n\n    -- ── CAPA OVERRIDES: exista o no el base, pero SOLO desde una cedida viva ──\n    -- La misma guarda de origen que arriba, y por la misma razón. Sin ella el\n    -- tapón tiene un agujero: los 307 productos que YA existen incluyen los de\n    -- las marcas propias, y sus precios por canal se recalculaban contra el\n    -- espejo de la org muerta. Medido: de 43 precios, 22 salían de ahí.\n    -- No es una guarda de frescura sobre una fuente vieja — es la misma\n    -- pregunta de siempre: ¿esta fuente tiene derecho a existir?\n    --\n    -- En ensayo, cuando el base todavía no existe, v_menu_id es NULL: el\n    -- EXISTS de abajo no encuentra nada y el override cuenta como nuevo, que\n    -- es justo lo que pasaría de verdad.\n    IF NOT COALESCE(v_prod.de_cedida, false) THEN\n      v_over_norg := v_over_norg + 1;\n      CONTINUE;\n    END IF;\n\n    FOR v_chan IN\n      SELECT sc.id AS channel_id, sc.slug,\n             (SELECT ecp3.price_cents\n                FROM external_catalog_product ecp3\n               WHERE ecp3.account_id = p_account_id\n                 AND ecp3.organization_product_id::text = v_prod.matricula\n                 AND ecp3.external_channel = sc.slug\n                 AND ecp3.price_cents IS NOT NULL\n               ORDER BY ecp3.seen_in_catalog_at DESC NULLS LAST\n               LIMIT 1) AS chan_cents\n      FROM sales_channel sc\n      WHERE sc.account_id = p_account_id\n        AND sc.slug IN ('glovo','uber','justeat','shop')\n    LOOP\n      IF v_chan.chan_cents IS NOT NULL\n         AND v_chan.chan_cents IS DISTINCT FROM COALESCE(v_prod.base_cents, -1) THEN\n        IF NOT EXISTS (\n          SELECT 1 FROM menu_item_override o\n          WHERE o.account_id = p_account_id\n            AND o.menu_item_id = v_menu_id\n            AND o.channel_id = v_chan.channel_id\n            AND o.location_id IS NULL\n        ) THEN\n          IF NOT p_dry_run THEN\n            INSERT INTO menu_item_override (account_id, menu_item_id, channel_id, location_id, price)\n            VALUES (p_account_id, v_menu_id, v_chan.channel_id, NULL,\n                    v_chan.chan_cents::numeric / 100.0);\n          END IF;\n          v_over := v_over + 1;\n          -- Se cuenta, no se corta: cuántos de esos precios salen de una foto\n          -- que no es la última. La guarda, si la quiere, la decide Julio.\n          IF NOT COALESCE(v_prod.en_foto_de_cedida, false) THEN\n            v_over_vieja := v_over_vieja + 1;\n          END IF;\n        END IF;\n      END IF;\n    END LOOP;\n  END LOOP;\n\n  dry_run                          := p_dry_run;\n  matriculas_miradas               := v_mir;\n  base_ya_existentes               := v_ya;\n  productos_base_creados           := v_base;\n  overrides_creados                := v_over;\n  overrides_de_foto_vieja          := v_over_vieja;\n  productos_sin_revisar_precios    := v_over_norg;\n  saltados_sin_marca               := v_nomarca;\n  saltados_por_integracion_no_cedida := v_norg;\n  saltados_por_ser_propia          := v_propia;\n  saltados_por_no_estar_en_la_foto := v_vieja;\n  marcas_sin_resolver              := v_marcas_nom;\n  marcas_de_integracion_no_cedida  := v_marcas_org;\n  marcas_propias_saltadas          := v_marcas_pro;\n  no_en_la_foto                    := v_lista;\n  fotos                            := v_fotos;\n  RETURN NEXT;\nEND;\n$function$\n	d719fe961173c7728cba1f2569809606	2026-10-27 22:00:59.162804+00
public.tg_clock_entry_debounce()	20261027T1112_l00_origen_del_fichaje	CREATE OR REPLACE FUNCTION public.tg_clock_entry_debounce()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nbegin\n  if coalesce(new.source,'kiosko') = 'kiosko' then\n    if exists (\n      select 1 from public.clock_entries c\n      where c.employee_id = new.employee_id\n        and coalesce(c.voided,false) = false\n        and abs(extract(epoch from (\n              coalesce(c.real_datetime,c.datetime) - coalesce(new.real_datetime,new.datetime)\n            ))) < 60\n    ) then\n      raise exception 'DOBLE_FICHAJE_MUY_RAPIDO'\n        using hint = 'Ya se registró un fichaje hace unos segundos.';\n    end if;\n  end if;\n  return new;\nend $function$\n	954e95101a050722607fbde592a32bc0	2026-10-27 21:45:37.099282+00
public.tg_goods_receipt_path_factura()	20261029T1012_s01c_facturas_solas	CREATE OR REPLACE FUNCTION public.tg_goods_receipt_path_factura()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare g goods_receipt; v jsonb; v_corte date;\nbegin\n  if current_setting('folvy.compras_factura', true) = 'si' then return null; end if;\n  if new.path <> 'factura' or new.supplier_invoice_id is not null or new.consumed_at is not null then\n    return null;\n  end if;\n  select * into g from goods_receipt where id = new.goods_receipt_id;\n  if g.status <> 'confirmado' or g.ai_session_id is null then return null; end if;\n  select max(fy.imported_until) into v_corte from fiscal_year fy where fy.company_id = new.company_id;\n  perform set_config('folvy.compras_factura', 'si', true);\n  if v_corte is not null and g.receipt_date <= v_corte then\n    update goods_receipt_path set reason = reason || format(' Es anterior al corte (%s): la lleva el programa anterior.', to_char(v_corte, 'DD/MM/YYYY'))\n     where id = new.id and reason not like '%anterior al corte%';\n  else\n    begin\n      v := public._compras_factura_desde_papel(g.account_id, g.ai_session_id, g.supplier_id, g.location_id, new.company_id, g.id, null);\n      if coalesce((v->>'sin_importes')::boolean, false) then\n        update goods_receipt_path set question = 'factura_sin_importes', question_detail = jsonb_build_object('motivo', v->>'motivo')\n         where id = new.id;\n      else\n        update goods_receipt_path set supplier_invoice_id = (v->>'factura')::uuid, consumed_at = now(),\n               question = case when coalesce((v->>'repetida')::boolean, false) then 'factura_repetida' else question end,\n               question_detail = case when coalesce((v->>'repetida')::boolean, false)\n                                      then jsonb_build_object('motivo', v->>'motivo', 'factura', v->>'factura') else question_detail end\n         where id = new.id;\n      end if;\n    exception when others then\n      perform set_config('folvy.compras_factura', 'si', true);\n      update goods_receipt_path set question = 'error', error = sqlerrm,\n             question_detail = jsonb_build_object('motivo', 'Folvy no pudo crear la factura desde el documento.')\n       where id = new.id;\n    end;\n  end if;\n  perform set_config('folvy.compras_factura', '', true);\n  return null;\nend $function$\n	e4032d0805eef7d76fa4d53b02a01ba3	2026-10-30 08:34:55.888432+00
public.ticket_invoice_ajustes(uuid)	20261027T1322_f01_sembrado_y_socio	CREATE OR REPLACE FUNCTION public.ticket_invoice_ajustes(p_account uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_a public.accounts; v_year integer := extract(year from (now() at time zone 'Europe/Madrid'))::integer;\nbegin\n  if p_account is null or not public.belongs_to_account(p_account) then raise exception 'No eres de esta cuenta.' using errcode = '42501'; end if;\n  select * into v_a from public.accounts where id = p_account;\n  return jsonb_build_object(\n    'año', v_year,\n    -- Sin el fabricante de Sumied no se pasa a real (verifactu_modo): se avisa aquí.\n    'fabricante_falta', not public.verifactu_sistema_completo(),\n    'empresas', (select coalesce(jsonb_agg(jsonb_build_object('company_id', c.id, 'nombre', coalesce(c.legal_name, c.trade_name),\n                    'nif', c.tax_id, 'verifactu', coalesce(e.modo, 'apagado'), 'real_desde', e.real_desde,\n                    'conexion_probada', coalesce(public.verifactu_conexion_probada(case when e.modo = 'real' then 'real' else 'pruebas' end,\n                                                   regexp_replace(upper(coalesce(c.tax_id, '')), '^ES', '')), false))\n                    order by coalesce(c.legal_name, c.trade_name)), '[]'::jsonb)\n                   from public.company c left join public.verifactu_empresa e on e.company_id = c.id\n                  where c.account_id = p_account and coalesce(c.is_active, true)),\n    'locales', (select coalesce(jsonb_agg(jsonb_build_object('location_id', l.id, 'nombre', l.name, 'activo', l.active,\n                    'codigo', lic.code, 'propuesto', public._ticket_codigo_propuesto(l.name, v_a.name),\n                    'empresa', (select coalesce(c.legal_name, c.trade_name) from public.location_company lc join public.company c on c.id = lc.company_id\n                                 where lc.location_id = l.id and lc.account_id = p_account),\n                    'tramo', x.tramo,\n                    'serie', case when lic.code is not null then public._ticket_numero_texto(lic.code, v_year, x.tramo, 'F', 1) end,\n                    'ultimo', (select last_number from public.ticket_invoice_series s where s.account_id = p_account and s.location_id = l.id\n                                 and s.year = v_year and s.kind = 'F' and s.tramo is not distinct from x.tramo),\n                    'ultimo_at', (select max(t.issued_at) from public.ticket_invoice t where t.account_id = p_account and t.location_id = l.id and t.kind = 'F'),\n                    'rectificativas', case when lic.code is not null then public._ticket_numero_texto(lic.code, v_year, x.tramo_r, 'R', 1) end,\n                    'ultimo_r', (select last_number from public.ticket_invoice_series s where s.account_id = p_account and s.location_id = l.id\n                                   and s.year = v_year and s.kind = 'R' and s.tramo is not distinct from x.tramo_r),\n                    'numeros', (select count(*) from public.ticket_invoice t where t.account_id = p_account and t.location_id = l.id),\n                    'verifactu_pendientes', (select count(*) from public.ticket_invoice t where t.account_id = p_account and t.location_id = l.id\n                                               and t.verifactu_estado in ('pendiente', 'anulacion_pendiente')))\n                    order by l.active desc, l.name), '[]'::jsonb)\n                  from public.locations l left join public.location_invoice_code lic on lic.location_id = l.id and lic.account_id = p_account\n                  cross join lateral (select public._ticket_tramo(p_account, l.id, v_year, 'F') as tramo,\n                                             public._ticket_tramo(p_account, l.id, v_year, 'R') as tramo_r) x\n                 where l.account_id = p_account),\n    'marcas', (select coalesce(jsonb_agg(jsonb_build_object('brand_id', b.id, 'nombre', b.name, 'propia', coalesce(b.ownership_type, 'own') <> 'licensed',\n                    -- Quién emite la de una cedida: lo que dice su último pedido de Last (30 días).\n                    'emisor', case when b.ownership_type = 'licensed' then (\n                       select public.safe_jsonb(s.raw_tab)->'bills'->0->'company'->>'name' from public.sale s\n                        where s.account_id = p_account and s.brand_id = b.id and s.sold_at > now() - interval '30 days'\n                          and public.safe_jsonb(s.raw_tab)->'bills'->0->'company'->>'name' is not null\n                        order by s.sold_at desc limit 1) end)\n                    order by (coalesce(b.ownership_type, 'own') = 'licensed'), b.name), '[]'::jsonb)\n                 from public.brand b where b.account_id = p_account and b.is_active and b.archived_at is null),\n    -- Pedidos de cedidas de los últimos 7 días sin la factura de Last (sus tiques salen sin la línea).\n    'cedidas_sin_factura_7d', (select count(*) from public.sale s join public.brand b on b.id = s.brand_id and b.account_id = s.account_id\n                                 where s.account_id = p_account and b.ownership_type = 'licensed' and s.sold_at > now() - interval '7 days'\n                                   and nullif(btrim(public.safe_jsonb(s.raw_tab)->'bills'->0->>'number'), '') is null));\nend $function$\n	517376b2398a88f2f666970cc3c8d6da	2026-10-27 22:00:59.162804+00
public.ticket_invoice_ajustes(uuid)	20261027T0741_v04_tique_verifactu	CREATE OR REPLACE FUNCTION public.ticket_invoice_ajustes(p_account uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_a public.accounts; v_year integer := extract(year from (now() at time zone 'Europe/Madrid'))::integer;\nbegin\n  if p_account is null or not public.belongs_to_account(p_account) then raise exception 'No eres de esta cuenta.' using errcode = '42501'; end if;\n  select * into v_a from public.accounts where id = p_account;\n  return jsonb_build_object(\n    'año', v_year,\n    'empresas', (select coalesce(jsonb_agg(jsonb_build_object('company_id', c.id, 'nombre', coalesce(c.legal_name, c.trade_name),\n                    'nif', c.tax_id, 'verifactu', coalesce(e.modo, 'apagado'),\n                    'conexion_probada', coalesce(public.verifactu_conexion_probada(case when e.modo = 'real' then 'real' else 'pruebas' end,\n                                                   regexp_replace(upper(coalesce(c.tax_id, '')), '^ES', '')), false))\n                    order by coalesce(c.legal_name, c.trade_name)), '[]'::jsonb)\n                   from public.company c left join public.verifactu_empresa e on e.company_id = c.id\n                  where c.account_id = p_account and coalesce(c.is_active, true)),\n    'locales', (select coalesce(jsonb_agg(jsonb_build_object('location_id', l.id, 'nombre', l.name, 'activo', l.active,\n                    'codigo', lic.code, 'propuesto', public._ticket_codigo_propuesto(l.name, v_a.name),\n                    'empresa', (select coalesce(c.legal_name, c.trade_name) from public.location_company lc join public.company c on c.id = lc.company_id\n                                 where lc.location_id = l.id and lc.account_id = p_account),\n                    'serie', case when lic.code is not null then public._ticket_invoice_text(lic.code, v_year, 'F', 1) end,\n                    'ultimo', (select last_number from public.ticket_invoice_series s where s.account_id = p_account and s.location_id = l.id and s.year = v_year and s.kind = 'F'),\n                    'ultimo_at', (select max(t.issued_at) from public.ticket_invoice t where t.account_id = p_account and t.location_id = l.id and t.kind = 'F'),\n                    'rectificativas', case when lic.code is not null then public._ticket_invoice_text(lic.code, v_year, 'R', 1) end,\n                    'ultimo_r', (select last_number from public.ticket_invoice_series s where s.account_id = p_account and s.location_id = l.id and s.year = v_year and s.kind = 'R'),\n                    'numeros', (select count(*) from public.ticket_invoice t where t.account_id = p_account and t.location_id = l.id))\n                    order by l.active desc, l.name), '[]'::jsonb)\n                  from public.locations l left join public.location_invoice_code lic on lic.location_id = l.id and lic.account_id = p_account\n                 where l.account_id = p_account),\n    'marcas', (select coalesce(jsonb_agg(jsonb_build_object('brand_id', b.id, 'nombre', b.name, 'propia', coalesce(b.ownership_type, 'own') <> 'licensed',\n                    -- Quién emite la de una cedida: lo que dice su último pedido de Last (30 días).\n                    'emisor', case when b.ownership_type = 'licensed' then (\n                       select public.safe_jsonb(s.raw_tab)->'bills'->0->'company'->>'name' from public.sale s\n                        where s.account_id = p_account and s.brand_id = b.id and s.sold_at > now() - interval '30 days'\n                          and public.safe_jsonb(s.raw_tab)->'bills'->0->'company'->>'name' is not null\n                        order by s.sold_at desc limit 1) end)\n                    order by (coalesce(b.ownership_type, 'own') = 'licensed'), b.name), '[]'::jsonb)\n                 from public.brand b where b.account_id = p_account and b.is_active and b.archived_at is null),\n    -- Pedidos de cedidas de los últimos 7 días sin la factura de Last (sus tiques salen sin la línea).\n    'cedidas_sin_factura_7d', (select count(*) from public.sale s join public.brand b on b.id = s.brand_id and b.account_id = s.account_id\n                                 where s.account_id = p_account and b.ownership_type = 'licensed' and s.sold_at > now() - interval '7 days'\n                                   and nullif(btrim(public.safe_jsonb(s.raw_tab)->'bills'->0->>'number'), '') is null));\nend $function$\n	d8f596306cc0d9eda69227a6e8553ff5	2026-10-27 09:45:29.27972+00
public.verifactu_modo(uuid,text,text,text,text)	20261027T0741_v04_tique_verifactu	CREATE OR REPLACE FUNCTION public.verifactu_modo(p_company uuid, p_modo text, p_serie text DEFAULT NULL::text, p_confirmacion text DEFAULT NULL::text, p_quien_nombre text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_co public.company; v_e public.verifactu_empresa; v_serie text := upper(btrim(coalesce(p_serie, ''))); v_hoy date := (now() at time zone 'Europe/Madrid')::date;\n  v_quien text := coalesce(p_quien_nombre, public.conta_nombre_actor());\nbegin\n  select * into v_co from public.company where id = p_company;\n  if v_co.id is null or not public.belongs_to_account(v_co.account_id) then raise exception 'Esa empresa no está.' using errcode = 'P0002'; end if;\n  if not public.current_user_is_admin_or_manager_of(v_co.account_id) then raise exception 'Solo un administrador o un encargado de la cuenta cambia Verifactu.' using errcode = '42501'; end if;\n  if p_modo not in ('apagado', 'pruebas', 'real') then raise exception 'Verifactu va apagado, en pruebas o en real.' using errcode = '22023'; end if;\n  insert into public.verifactu_empresa (company_id, account_id) values (v_co.id, v_co.account_id) on conflict (company_id) do nothing;\n  select * into v_e from public.verifactu_empresa where company_id = p_company for update;\n  if v_e.modo = p_modo then return jsonb_build_object('modo', v_e.modo, 'cambiado', false); end if;\n  -- EL CANDADO (respuesta 3 de Julio): a pruebas o a real, solo con una prueba\n  -- de conexión correcta con la AEAT apuntada. En pruebas, la del entorno de\n  -- pruebas; en real, la de real con el NIF de esta empresa.\n  if p_modo in ('pruebas', 'real') and not public.verifactu_conexion_probada(p_modo, v_co.tax_id) then\n    raise exception '%', case p_modo\n      when 'pruebas' then 'Todavía no se ha probado la conexión con el entorno de pruebas de Hacienda: hasta que salga bien, Verifactu no se puede poner en pruebas.'\n      else 'Todavía no se ha probado la conexión con Hacienda con el certificado de esta empresa: hasta que salga bien, Verifactu no se puede pasar a real.' end\n      using errcode = '23514';\n  end if;\n  if v_e.modo = 'real' and v_hoy <= v_e.real_obliga_hasta then\n    raise exception 'Estás en real desde el %: la ley obliga a seguir así hasta el % (Orden HAC/1177/2024, art. 17.2).',\n      to_char(v_e.real_desde at time zone 'Europe/Madrid', 'DD/MM/YYYY'), to_char(v_e.real_obliga_hasta, 'DD/MM/YYYY') using errcode = '23514';\n  end if;\n  if p_modo = 'real' then\n    if p_confirmacion is distinct from 'EMPEZAR' then raise exception 'Para pasar a real, escribe EMPEZAR: desde ese momento no se puede volver a pruebas este año.' using errcode = '23514'; end if;\n    if not public._verifactu_nif_es_valido(v_co.tax_id) then raise exception 'El NIF de tu empresa no es válido: corrígelo antes de pasar a real.' using errcode = '23514'; end if;\n    if v_serie !~ '^[A-Z0-9][A-Z0-9-]{0,9}$' then raise exception 'La serie nueva va en mayúsculas y cifras (por ejemplo F%).', extract(year from v_hoy)::int using errcode = '23514'; end if;\n    if exists (select 1 from public.customer_invoice where company_id = p_company and series_code = v_serie and status <> 'borrador') then\n      raise exception 'La serie % ya tiene facturas: la de real empieza nueva.', v_serie using errcode = '23514';\n    end if;\n    if not exists (select 1 from public.invoice_series where company_id = p_company and code = v_serie) then\n      insert into public.invoice_series (account_id, company_id, code, name, doc_type, digits, reset_yearly, starts_at, is_default, is_active)\n      values (v_co.account_id, v_co.id, v_serie, 'Facturas (Verifactu)', 'invoice', 4, true, 1, false, true);\n    end if;\n    update public.verifactu_empresa set modo = 'real', real_desde = now(), real_serie = v_serie,\n           real_obliga_hasta = make_date(extract(year from v_hoy)::int, 12, 31), updated_at = now(), updated_by_name = v_quien\n     where company_id = p_company;\n  else\n    update public.verifactu_empresa set modo = p_modo, real_desde = null, real_serie = null, real_obliga_hasta = null,\n           pruebas_desde = case when p_modo = 'pruebas' then now() else pruebas_desde end, updated_at = now(), updated_by_name = v_quien\n     where company_id = p_company;\n  end if;\n  select * into v_e from public.verifactu_empresa where company_id = p_company;\n  return jsonb_build_object('modo', v_e.modo, 'cambiado', true, 'real_desde', v_e.real_desde, 'real_serie', v_e.real_serie, 'real_obliga_hasta', v_e.real_obliga_hasta);\nend $function$\n	d34603423df8f6de8734eadf9e989334	2026-10-27 09:45:29.27972+00
public.void_clock_entry(uuid,text,text)	20261028T0706_l1a_corregir_con_conformidad	CREATE OR REPLACE FUNCTION public.void_clock_entry(p_entry_id uuid, p_reason text, p_actor_label text DEFAULT NULL::text)\n RETURNS clock_entries\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\ndeclare v_acct uuid; v_emp uuid; v_row public.clock_entries;\r\nbegin\r\n  if coalesce(trim(p_reason),'') = '' then raise exception 'MOTIVO_OBLIGATORIO'; end if;\r\n  select employee_id into v_emp from public.clock_entries where id = p_entry_id;\r\n  if v_emp is null then raise exception 'FICHAJE_NO_EXISTE'; end if;\r\n  v_acct := public._account_of_employee(v_emp);\r\n  if not public.current_user_is_admin_of(v_acct) then raise exception 'NO_AUTORIZADO'; end if;\r\n\r\n  perform set_config('app.clock_edit_reason', p_reason, true);\r\n  perform set_config('app.clock_edit_actor', coalesce(p_actor_label,''), true);\r\n\r\n  update public.clock_entries set voided = true where id = p_entry_id returning * into v_row;\r\n  return v_row;\r\nend $function$\n	dba9ae6a47d2488949848435bae1a48a	2026-10-28 09:27:45.141282+00
\.
